"""Bilingual editorial source. [[ID]] resolves a citation; {{figure}} inserts an original or credited figure."""
from pathlib import Path
import runpy

_dashboard = runpy.run_path(str(Path(__file__).with_name('dashboard.py')))
status_grid = _dashboard['status_grid']
acquisition_calculator = _dashboard['acquisition_calculator']
horizon = _dashboard['horizon']
PAGES = {}

def page(key, ja_title, en_title, ja_lead, en_lead, sections):
    PAGES[key] = dict(title={'ja': ja_title, 'en': en_title}, lead={'ja': ja_lead, 'en': en_lead}, sections=sections)

def s(key, ja_title, en_title, ja, en):
    return dict(id=key, title={'ja': ja_title, 'en': en_title}, body={'ja': ja, 'en': en})

page('index',
     'マインドアップロードを、実験可能な研究へ。',
     'Make mind uploading an experimental science.',
     '脳を測り、モデルを作り、同じ条件で確かめる。全脳エミュレーションの実現に必要な技術と、次に解くべき問題を一次資料から整理します。',
     'Measure a brain, build a model, and test both under matched conditions. A source-grounded guide to the technologies and experiments needed for whole-brain emulation.', [
    s('at-a-glance', 'いま、どこまで来ましたか', 'Where are we now?',
      '<p class="dashboard-lead"><strong>ハエ脳の地図化と、限定的な機能予測は実証済み。</strong>次の核心は、測った脳から、その個体の記憶や学習を再現して確かめることです。</p>' + status_grid('ja') + '<p class="small">各ラベルは、確認した文献に基づく到達段階です。人の全脳再現を何％完成したかという尺度ではありません。</p><h3>2050年に間に合わせるための必要条件</h3>' + horizon('ja') + '<p class="small">年は本サイトの研究計画案です。各段階の通過条件を満たすことを前提にします。</p><p><a class="button" href="/ja/history.html#dashboard">現在地・残る12課題・2050年の道筋を見る →</a></p>',
      '<p class="dashboard-lead"><strong>Fly-brain wiring maps and limited functional predictions have been demonstrated.</strong> The next core challenge is to recover and test the original individual’s memory and learning from measured brain data.</p>' + status_grid('en') + '<p class="small">Labels summarise stages supported by the reviewed evidence. They are not percentages of completed human whole-brain emulation.</p><h3>Five review gates toward a 2050 target</h3>' + horizon('en') + '<p class="small">Dates are this site’s proposed planning targets, conditional on passing each gate.</p><p><a class="button" href="/history.html#dashboard">Explore the current position, 12 tasks and the path to 2050 →</a></p>'),
    s('starting-point',
      '何を実現したいのでしょうか',
      'What are we trying to build?',
      '<p><strong>マインドアップロード</strong>は、脳が担う情報処理を別の媒体で実現する構想です。その技術的な道筋の一つが<strong>全脳エミュレーション（WBE）</strong>です。特定の個体の脳を測り、その個体に固有の応答や学習済みの機能を計算機上で再現することを目指します。必要なのは、よく動くモデルに加えて、<strong>元の個体との対応を確かめる実験</strong>です。[[CCFAQ]][[XKB4CG64]]</p><div class="key"><p><strong>次に解く問い：</strong>何を、どの精度で測れば、元の個体を平均的な脳のモデルよりよく予測できるのでしょうか。本サイトでは、この問いを測定・モデル化・検証に分けて扱います。</p><p><strong>未到達の点：</strong>本サイトで本文を確認した研究には、個体が生前に獲得した記憶を取り出し、全脳モデルで再現・検証した例はありません。これは調査対象についての結論であり、分野全体の不存在を証明するものではありません。[[REPORTFINAL]]</p></div>{{pipeline}}',
      '<p><strong>Mind uploading</strong> is the proposed implementation of brain-based information processing in another medium. One technical route is <strong>whole-brain emulation (WBE)</strong>: measuring a particular brain and reproducing its individual responses and learned functions computationally. The central requirement is an experiment that tests correspondence to the original individual.[[CCFAQ]][[XKB4CG64]]</p><div class="key"><p><strong>The next question:</strong> what must be measured, and at what precision, to predict the original individual better than an average-brain model? This guide separates that question into measurement, modelling and validation.</p><p><strong>Still unachieved:</strong> none of the research whose full text we reviewed demonstrates extraction of an individual\'s previously acquired memories followed by their reproduction and validation in a whole-brain model. This is a conclusion about the reviewed evidence, not proof of absence across the entire field.[[REPORTFINAL]]</p></div>{{pipeline}}'),
    s('milestones',
      '測る・作る・確かめる：現在の前進',
      'Measure, build, validate: current advances',
      '<div class="cards"><article class="card"><span class="tag">測る · 構造</span><h3>ハエの脳全体から中枢神経系へ</h3><p>FlyWireは雌成体脳の139,255ニューロンを再構成しました。2026年のBANCとMaleCNSは、脳と腹側神経索を結ぶ回路を調べる独立した基盤です。[[ADD196]][[ADD199]][[ADD188]]</p></article><article class="card"><span class="tag">測る · 構造と活動</span><h3>同じ組織で接続と応答を対応付ける</h3><p>MICrONSはマウス視覚野の部分体積で、生体の活動記録と固定後の電子顕微鏡像を対応付けました。活動を記録した細胞数と、構造に対応付けた細胞数は区別して読みます。[[6TNZ57MZ]]</p></article><article class="card"><span class="tag">作る · 機能予測</span><h3>接続図から実験可能な予測へ</h3><p>ハエの感覚運動回路と視覚系では、接続図を使ったモデルの予測を実験データと照合する研究が進んでいます。[[V4GV7JAJ]][[XMYSQXY8]]</p></article><article class="card"><span class="tag">確かめる · 比較</span><h3>復元法を同じ条件で試す</h3><p>ZAPBenchは神経活動の予測を、Brain Emulation Challengeは正解が分かる人工回路の復元を評価する入口になります。[[FHPYMIG8]][[CCCHALLENGE]]</p></article></div>{{flywire}}',
      '<div class="cards"><article class="card"><span class="tag">Measure · structure</span><h3>From the fly brain to the central nervous system</h3><p>FlyWire reconstructed 139,255 neurons in an adult female brain. BANC and MaleCNS, reported in 2026, are independent resources for circuits connecting the brain and ventral nerve cord.[[ADD196]][[ADD199]][[ADD188]]</p></article><article class="card"><span class="tag">Measure · structure and activity</span><h3>Pair connections with responses</h3><p>MICrONS links live activity recordings and subsequent electron microscopy in a partial volume of mouse visual cortex. The number of recorded cells and the number matched to the structural reconstruction must be distinguished.[[6TNZ57MZ]]</p></article><article class="card"><span class="tag">Build · functional prediction</span><h3>Turn wiring into testable predictions</h3><p>Connectome-based models of fly sensorimotor circuits and the visual system have been compared with experimental measurements.[[V4GV7JAJ]][[XMYSQXY8]]</p></article><article class="card"><span class="tag">Validate · comparison</span><h3>Test methods under matched conditions</h3><p>ZAPBench evaluates neural activity prediction; the Brain Emulation Challenge provides a framework for reconstructing artificial circuits with known ground truth.[[FHPYMIG8]][[CCCHALLENGE]]</p></article></div>{{flywire}}'),
    s('carboncopies',
      'Carboncopiesが取り組む「測定からモデルへ」',
      'Carboncopies: from measurements to models',
      '<p>Carboncopies Foundationの現在の研究計画では、<strong>Brain Emulation Challenge</strong>、開発基盤の<strong>BrainGenix</strong>、WBEロードマップの更新が重要な柱です。Challengeでは正解が既知の人工神経回路を使い、制限された観測からどこまで機能を復元できるかを調べます。生物学的実証とは区別しながら、方法を比較できる実験環境を作る取り組みです。[[CCRESEARCH]][[CCCHALLENGE]]</p><p><a class="button" href="carboncopies.html">Carboncopiesの研究を詳しく見る →</a></p>',
      '<p>Current Carboncopies Foundation work centres on the <strong>Brain Emulation Challenge</strong>, the <strong>BrainGenix</strong> platform, and an updated WBE roadmap. The Challenge uses synthetic circuits with known ground truth to test reconstruction from limited observations. This provides a controlled comparison of methods; biological validation is a separate step.[[CCRESEARCH]][[CCCHALLENGE]]</p><p><a class="button" href="carboncopies.html">Explore Carboncopies research →</a></p>'),
    s('read',
      '研究の道筋をたどる',
      'Follow the research path',
      '<p>はじめて読む方は、<a href="/ja/science.html#glossary">用語と科学的基礎</a>から、<a href="/ja/progress.html">到達点</a>へ進んでください。研究に着手する方は、<a href="/ja/validation.html#individual">個体との対応の検証</a>、<a href="/ja/future.html">研究戦略と展望</a>、<a href="/ja/action.html">最初の研究課題</a>を続けて読めます。</p><p><a href="/ja/resources.html">文献一覧</a>には、本文を確認して本解説に用いた資料だけを掲載しています。研究成果、理論、プレプリント、団体・企業の説明、本サイトの研究提案を分けて記載しています。</p>',
      '<p>Start with <a href="/science.html#glossary">terms and scientific foundations</a>, then the <a href="/progress.html">evidence</a>. To begin a project, continue to <a href="/validation.html#individual">individual correspondence</a>, <a href="/future.html">research strategy and outlook</a>, and the <a href="/action.html">first research project</a>.</p><p>The <a href="/resources.html">library</a> contains only sources whose full text was reviewed and used in this guide. Empirical findings, theory, preprints, organisational statements and this site\'s research proposals are distinguished.</p>'),
])

page('science',
     '脳を再現するには、何を測る必要がありますか',
     'What must we measure to reproduce a brain?',
     '接続、細胞の応答、可塑性、分子状態、身体との相互作用。それぞれの情報が何を制約するのかを整理します。',
     'Connectivity, cellular responses, plasticity, molecular state, and interaction with a body constrain different aspects of a model.', [
    s('glossary',
      '用語を混同しないために',
      'Terms that should remain distinct',
      '<dl class="glossary"><dt>コネクトーム（接続図）</dt><dd>指定した範囲の神経接続データです。細胞数、領域、化学・電気シナプスの範囲を併記します。</dd><dt>シミュレーションとエミュレーション</dt><dd>前者は仮定したモデルの計算、後者は対象となる系との機能的な対応を目指す再現です。</dd><dt>システム同定・逆問題</dt><dd>観測した入力・出力から、モデルの形やパラメーターを推定することです。観測を生む原因を推定するため、逆問題になります。</dd><dt>識別可能性</dt><dd>利用できる観測によって、異なるモデルを区別できる性質です。</dd><dt>忠実度</dt><dd>あらかじめ決めた機能と条件で、元の系にどの程度対応するかです。</dd><dt>閉ループ</dt><dd>感覚が行動を変え、その行動が次の感覚を変える循環です。</dd><dt>カルシウム活動</dt><dd>細胞内カルシウムの変化を用いた活動の間接的な観測です。膜電位や全スパイクを直接測るものとは区別します。</dd><dt>エングラム</dt><dd>記憶の保持や想起に関わる物理的変化・細胞集団を調べる概念です。</dd><dt>プレプリント</dt><dd>査読による正式出版前に公開された原稿です。版と公開日を確認します。</dd></dl>',
      '<dl class="glossary"><dt>Connectome</dt><dd>Connectivity data within a specified boundary. Report cell coverage, regions, and chemical or electrical synapse coverage.</dd><dt>Simulation and emulation</dt><dd>Simulation computes an assumed model. Emulation aims at functional correspondence to a specified target system.</dd><dt>System identification and inverse problem</dt><dd>Inferring model form or parameters from observed inputs and outputs. It is an inverse problem because the causes of observations must be inferred.</dd><dt>Identifiability</dt><dd>The ability to distinguish different models using available observations.</dd><dt>Fidelity</dt><dd>Correspondence to the original system for explicitly defined functions and conditions.</dd><dt>Closed loop</dt><dd>Sensation changes action, which changes subsequent sensation.</dd><dt>Calcium activity</dt><dd>An indirect observation of activity through intracellular calcium changes, distinct from directly measuring voltage or every spike.</dd><dt>Engram</dt><dd>A concept for studying physical changes and cell ensembles involved in memory retention and recall.</dd><dt>Preprint</dt><dd>A manuscript released before formal peer-reviewed publication; identify its version and date.</dd></dl>'),
    s('state',
      '構造・状態・更新規則を分ける',
      'Separate structure, state, and update rules',
      '<p>以下は本サイトが説明のために用いる<strong>概念的な表記</strong>です。単一の既存論文の式や、完成した脳モデルを転載したものではありません。</p><p><code>x(t+Δt) = F(x(t), u(t); θ(t))</code><br><code>θ(t+Δt) = G(θ(t), x(t), u(t))</code></p><p><strong>x</strong>は膜電位や適応などの速い状態、<strong>u</strong>は入力、<strong>θ</strong>は接続強度や伝達特性、<strong>F</strong>は応答、<strong>G</strong>は学習や可塑性による変化を表します。何を状態とパラメーターに分けるかは時間尺度に依存します。点ニューロンか多区画モデルかという<strong>モデルの形そのもの</strong>も選択・検証の対象です。膜電流の定量モデルと、入出力からの神経系同定が、これを考える基礎になります。[[ADD207]][[VC2JX6XE]]</p>{{state}}<p>接続図に加えて、受容体や神経修飾によって応答が変わり得ます。必要な詳細度は、「全部を細かくする」ことだけでは決まりません。省略した要素を戻したときに、独立した評価条件で予測が改善するかを調べます。[[ADD187]][[XKB4CG64]]</p>',
      "<p>The following is this site's <strong>conceptual notation</strong>, not an equation reproduced from a particular paper or a completed brain model.</p><p><code>x(t+Δt) = F(x(t), u(t); θ(t))</code><br><code>θ(t+Δt) = G(θ(t), x(t), u(t))</code></p><p><strong>x</strong> denotes fast states such as voltage and adaptation; <strong>u</strong>, inputs; <strong>θ</strong>, connection strengths and transmission properties; <strong>F</strong>, responses; and <strong>G</strong>, learning and plasticity. The distinction between state and parameter depends on timescale. Model form itself, such as point neurons versus multicompartment cells, also requires selection and validation. Quantitative membrane-current models and input–output system identification provide foundations.[[ADD207]][[VC2JX6XE]]</p>{{state}}<p>Receptors and neuromodulation can change responses beyond what a wiring diagram specifies. To choose necessary detail, test whether restoring an omitted mechanism improves predictions on independent evaluation conditions.[[ADD187]][[XKB4CG64]]</p>"),
    s('measurement',
      '異なる計測を組み合わせる',
      'Combine complementary measurements',
      '<div class="tbl"><table><thead><tr><th>計測</th><th>得られる主な情報</th><th>単独では不足する点</th></tr></thead><tbody><tr><td>電子顕微鏡（EM）</td><td>微細形態とシナプス接続</td><td>固定後の像から生前の活動履歴を直接読めるわけではありません。</td></tr><tr><td>拡大顕微鏡・分子標識</td><td>形態と標識した分子の位置</td><td>標識の抜け、歪み、対応付け、撮像量を評価する必要があります。</td></tr><tr><td>電気生理・カルシウム画像</td><td>時間変化、刺激応答、集団活動</td><td>全細胞の全状態を同時に観測できるとは限りません。</td></tr><tr><td>摂動と行動計測</td><td>介入への応答と入出力関係</td><td>同じ行動を別の内部機構で実現できる可能性が残ります。</td></tr><tr><td>グリアの標識・活動・選択的介入</td><td>細胞型、学習関連集団、神経活動への調節</td><td>形態だけで機能状態や記憶内容が分かるわけではありません。必要な状態は課題ごとに検証します。</td></tr><tr><td>ペプチド・受容体と誘発応答</td><td>シナプス外伝達を含む有効な信号伝播</td><td>遺伝子発現は放出量や受容体状態の直接測定ではなく、誘発応答には間接経路も含まれます。</td></tr></tbody></table></div><p>MICrONSは、同じ個体の構造と活動を対応付ける具体例です。LICONNは、組織を約16倍に拡大し、光学像から密な再構成と分子標識の併用を可能にしました。撮像した最大の組織体積は約100万 µm³（0.001 mm³）で、全脳規模の実証ではありません。分子標識には保持されにくい抗体・条件もあるため、目的とする分子ごとの確認が必要です。[[6TNZ57MZ]][[ADD198]]</p><p>測定方式は、解像度、体積、取得速度、欠損、費用、再構成誤差を合わせて比べます。撮像時間の試算を、保存から機能検証までの総所要時間と読み替えないことも重要です。[[EVWH7H32]]</p>{{liconn}}<p><strong>配線の外側にある伝達：</strong>Randiら（2023）は、動かない状態の<i>C. elegans</i>で単一ニューロンを光刺激し、頭部の23,433ニューロン対の信号伝播を調べました。濃芯小胞放出に関わる<em>unc-31</em>変異体との比較などから、解剖学的接続だけでは捉えられないシナプス外伝達の寄与を示しました。測るのは直接・間接経路を含む応答であり、単シナプスの接続数ではありません。特定モデルとの不一致を、配線に基づくモデルすべての失敗とは一般化できません。[[ISSUE283_RANDI2023]]</p><p>グリアや分子情報を全て測ることが必須だと結論したわけではありません。省略・追加モデルを同じ未使用条件で比較し、必要な測定を選ぶ方針です。<a href="/ja/validation.html#negative">省略要素の検証手順</a>をご覧ください。[[ISSUE283_WILLIAMSON2025]]</p>',
      '<div class="tbl"><table><thead><tr><th>Measurement</th><th>Main information</th><th>What it does not supply alone</th></tr></thead><tbody><tr><td>Electron microscopy</td><td>Fine morphology and synaptic connectivity</td><td>Fixed images do not directly reveal the previous activity history.</td></tr><tr><td>Expansion microscopy and molecular labels</td><td>Morphology and locations of labelled molecules</td><td>Label loss, distortion, registration and imaging volume require evaluation.</td></tr><tr><td>Electrophysiology and calcium imaging</td><td>Temporal changes, stimulus responses and population activity</td><td>Not every state of every cell is necessarily observed simultaneously.</td></tr><tr><td>Perturbation and behaviour</td><td>Intervention responses and input–output relations</td><td>Different mechanisms may produce similar behaviour.</td></tr><tr><td>Glial labels, activity and selective interventions</td><td>Cell types, learning-associated ensembles and modulation of neuronal activity</td><td>Morphology alone does not specify functional state or memory content. Required states must be tested for each task.</td></tr><tr><td>Peptides, receptors and evoked responses</td><td>Effective signal propagation including extrasynaptic transmission</td><td>Gene expression does not directly measure release or receptor state; evoked responses also include indirect paths.</td></tr></tbody></table></div><p>MICrONS provides paired structure and activity in the same animal. LICONN combines roughly sixteenfold tissue expansion, dense optical reconstruction and molecular labels. Its largest imaged native tissue volume was approximately one million µm³ (0.001 mm³), rather than a whole brain. Some antibodies and conditions do not survive the workflow well, so molecular targets require individual validation.[[6TNZ57MZ]][[ADD198]]</p><p>Compare resolution, volume, speed, missing data, cost and reconstruction errors together. Imaging-time estimates are not end-to-end estimates for preservation, reconstruction and functional validation.[[EVWH7H32]]</p>{{liconn}}<p><strong>Transmission beyond wiring:</strong> Randi et al. (2023) optogenetically stimulated individual neurons in immobilized <i>C. elegans</i> and measured propagation across 23,433 head-neuron pairs. Comparisons including <em>unc-31</em> mutants affecting dense-core-vesicle release supported contributions from extrasynaptic signalling. The measured response includes direct and indirect paths; it is not a count of monosynaptic connections. Mismatch with a particular anatomical model does not establish failure of every wiring-based model.[[ISSUE283_RANDI2023]]</p><p>This does not establish that every glial or molecular state must be measured. Compare models with and without candidate mechanisms on the same held-out conditions to select useful measurements. See the <a href="/validation.html#negative">omission tests</a>.[[ISSUE283_WILLIAMSON2025]]</p>'),
    s('inverse',
      'データからモデルへの逆問題',
      'The inverse problem from data to model',
      '<p>異なるパラメーターの回路から、似た活動が生じることがあります。この<strong>縮退</strong>は、観測に合う答えが一つとは限らないという問題です。[[ADD190]]</p><p>Hanらは正解の分かる人工視覚モデルを用い、活動予測の得点だけでは正しいモデル構造を選べない条件を示しました。一方、観測するユニットの範囲や刺激を変えると、識別しやすさも変わります。結論は「同定は不可能」ではなく、<strong>候補を区別できる観測を設計する必要がある</strong>ということです。[[274IXB72]]</p>{{inverse}}<p>研究上は、想定する介入の範囲で同じ機能を示すモデルの集合を、暫定的な到達点にできます。その際は、どの条件で同じと判定したかを明記し、未測定の条件まで同じだと外挿しません。接続、活動、課題、介入という異なる制約を組み合わせて候補を絞ります。[[XMYSQXY8]][[274IXB72]]</p><p><strong>不確実性を含めて推定する：</strong>シミュレーションベース推論では、一組の最適パラメーターだけでなく、指定したモデルMと事前分布の下で観測xに整合するパラメーターθの近似事後分布<code>p(θ | x, M)</code>を推定できます。Gonçalvesらは神経動態モデルで、同様の出力を生む複数の解とパラメーター間の補償関係を推定しました。ただし、分布はモデル・事前分布・観測特徴・ノイズ仮定に依存します。これ自体は、任意の介入での同等性や全脳の一意な復元の保証ではありません。[[ISSUE285_GONCALVES2020]]</p><p>本サイトの提案では、事後分布から予測を作り、未使用の刺激・介入で候補間の違いを調べます。正解が分かる人工モデルでの被覆率や、事前分布を変えた場合の安定性も検査します。具体的な評価項目は<a href="/ja/future.html#gates">M1</a>に示します。</p><p><strong>理論が支える範囲：</strong>NETTは、学習した正則化を用いる逆問題について、一定の連続性や強制性などの仮定の下で、解の存在・安定性・収束を解析しています。数値例は光音響画像の再構成です。ここでは神経回路の同定を直接扱う結果ではなく、一般的な逆問題の理論例として位置付けます。この種の保証は、制約付き推定を設計する手掛かりになりますが、脳の正しい状態を一意に復元できる保証へそのまま移せません。[[EB493XBG]]</p>',
      '<p>Circuits with different parameter settings can produce similar activity. This <strong>degeneracy</strong> means that fitting observations need not yield a unique answer.[[ADD190]]</p><p>Han and colleagues tested artificial vision models with known ground truth and found conditions in which activity-prediction scores did not select the correct model architecture. Identifiability also changed with unit coverage and stimulus choice. The lesson is to design observations that discriminate candidates, rather than to conclude that identification is impossible.[[274IXB72]]</p>{{inverse}}<p>As a research proposal, a set of models functionally equivalent over specified interventions can be a provisional target. State the tested conditions and do not assume equivalence outside them. Combine wiring, activity, task constraints and interventions to narrow the candidates.[[XMYSQXY8]][[274IXB72]]</p><p><strong>Estimate uncertainty:</strong> simulation-based inference can return an approximate posterior <code>p(θ | x, M)</code> over parameters θ compatible with observations x, conditional on a specified model M and prior, rather than only one optimum. Gonçalves and colleagues estimated multiple compatible solutions and compensatory parameter relationships in neural dynamics models. The distribution depends on the model, prior, observed features and noise assumptions. It does not by itself establish equivalence under arbitrary interventions or unique whole-brain reconstruction.[[ISSUE285_GONCALVES2020]]</p><p>Our proposed evaluation uses posterior predictions to distinguish candidates under held-out stimuli and interventions. It also checks interval coverage in artificial models with known ground truth and sensitivity to the prior. See <a href="/future.html#gates">M1</a> for the evaluation requirements.</p><p><strong>What theory can establish:</strong> NETT analyses existence, stability and convergence for inverse problems with learned regularization under assumptions including continuity and coercivity. Its numerical examples reconstruct photoacoustic images. Here it serves as general inverse-problem theory, rather than a direct result about identifying neural circuits. Such guarantees help design constrained inference, but do not automatically guarantee unique recovery of a brain\'s true state.[[EB493XBG]]</p>'),
    s('memory',
      '記憶を「保存できた」と言うための条件',
      'What would demonstrate retained memory?',
      '<p>Uytiepoら（2025）は、マウスの恐怖学習時に活動した細胞を標識し、1週間後の海馬の局所シナプス構造を調べました。主な電子顕微鏡比較は学習群3匹・対照群2匹で、複数の棘へ接続する終末などに差が見られました。一方、同時に標識された細胞同士が優先的につながるという単純な結果ではありません。<strong>学習に伴う構造差を捉えた研究</strong>であり、任意の記憶内容を解読した研究ではありません。[[LP5F3H2Q]]</p><p>記憶の構造的基盤を尋ねた研究者調査でも、必要な情報の尺度や実現可能性には見解の幅がありました。調査中の「静的構造」は個々の生体分子まで含む広い定義で、理想的な保存の成功を仮定しています。回答の割合を、復元成功率や保存された記憶の割合として読むことはできません。[[ADD210]]</p>{{memory}}<p>次の研究では、同じ個体の学習、測定、未使用の想起課題を対応付け、保持期間・忘却・再学習・介入後の変化を調べます。モデルへ評価課題の正解を追加学習させると、元の記憶から復元できたかを判定できなくなるため、学習と評価を分離します。</p><p><strong>神経細胞以外の寄与：</strong>マウス海馬では、学習時に標識したアストロサイト集団の再活性化とNFIAの選択的欠失により、恐怖記憶の想起行動への寄与が示されました。神経エングラムを人工活性化すると欠失群の想起行動が回復する結果もあります。アストロサイトだけに記憶が保存されることや、全脳再現に全グリアの全状態が必須であることを示した研究ではありません。[[ISSUE283_WILLIAMSON2025]]</p>',
      '<p>Uytiepo et al. (2025) labelled cells active during fear learning in mice and examined local hippocampal synaptic structure one week later. The main EM comparison used three conditioned and two control animals, finding differences including terminals contacting multiple spines. The result was not simply preferential wiring among co-labelled cells. This detects <strong>learning-associated structural differences</strong>; it does not decode arbitrary memory content.[[LP5F3H2Q]]</p><p>A researcher survey also found varied views on the structural scale and information needed for memory recovery. Its broad definition of static structure includes individual biomolecules and assumes successful, ideal preservation. Response percentages are neither measured recovery probabilities nor proportions of memories preserved.[[ADD210]]</p>{{memory}}<p>The next experiments should link learning, measurement and held-out recall in the same individual, examining retention, forgetting, relearning and intervention responses. Keep test answers out of model fitting, so the experiment can assess whether retained information, rather than additional answer training, supports recall.</p><p><strong>Contributions beyond neurons:</strong> In the mouse hippocampus, reactivation of learning-tagged astrocytes and selective NFIA deletion demonstrated contributions to fear-memory recall behaviour. Artificial neuronal-engram activation rescued recall behaviour after NFIA deletion. These results do not establish storage in astrocytes alone or a requirement to reproduce every glial state for whole-brain emulation.[[ISSUE283_WILLIAMSON2025]]</p>'),
    s('preservation',
      '保存は、復元までの連鎖の一段階です',
      'Preservation is one stage in a longer chain',
      '<p>アルデヒド安定化凍結保存（ASC）は、固定した組織の微細構造を保つ方法です。2015年の研究では、最終条件のウサギ8例と良好に処理できたブタ1例などを顕微鏡で評価しました。神経突起やシナプスを追跡できる像は得られましたが、生理機能や学習済み記憶の復元は評価していません。[[SDSWEA5J]]</p>{{preservation}}<p>次に必要なのは、保存前後で何が変わるかを測り、その損失が機能予測をどの程度変えるかまで追う実験です。微細構造の保持、必要な状態の保持、情報の読み出し、機能の検証は、それぞれ独立した到達点です。[[REPORTFINAL]]</p>',
      '<p>Aldehyde-stabilized cryopreservation (ASC) preserves the ultrastructure of chemically fixed tissue. The 2015 study examined, among other preparations, eight rabbits under the final protocol and one successfully processed pig. Images showed traceable neurites and synapses; restoration of physiological function or learned memories was not evaluated.[[SDSWEA5J]]</p>{{preservation}}<p>The next experimental task is to measure what preservation changes and how those losses affect functional prediction. Retaining ultrastructure, retaining necessary states, reading out information and validating function are separate milestones.[[REPORTFINAL]]</p>'),
])

page('progress',
     '到達点を、実験の範囲で読む',
     'Read progress at the scale of the experiment',
     '脳全体の構造、局所回路の機能、身体を含む行動。異なる成果を一つの完成率にまとめず、対象と検証内容を比較します。',
     'Whole-brain structure, local circuit function, and embodied behaviour are different achievements. Compare their scope and tests rather than assigning a single completion percentage.', [
    s('maps',
      '接続図の対象はどこまで広がりましたか',
      'How far do the wiring maps extend?',
      '<div class="tbl"><table><thead><tr><th>研究</th><th>対象と成果</th><th>解釈するときの境界</th></tr></thead><tbody><tr><td>Cook et al., 2019</td><td><i>C. elegans</i>の雌雄同体と雄について、全身の神経系を対象とする接続図。[[ADD192]]</td><td>複数個体の観測と一部の外挿を組み合わせた図です。一個体を漏れなく測った記録ではありません。</td></tr><tr><td>Winding et al., 2023</td><td>雌の初齢ハエ幼生1個体の脳、3,016ニューロン。[[ADD209]]</td><td>脳への入力を含む数です。腹側神経索全体や成体は対象外です。</td></tr><tr><td>FlyWire, 2024</td><td>雌成体ハエ1個体の脳、139,255ニューロンと再構成済みニューロン間の約5,450万の化学シナプス。[[ADD196]]</td><td>シナプス5個以上を持つ有向ニューロン対を辺とすると、134,181ニューロン間の2,700,513接続です。シナプス数と辺数を区別します。腹側神経索や電気シナプス、学習履歴は含みません。</td></tr><tr><td>H01, 2024</td><td>手術で得た人の側頭皮質約1 mm³。57,180細胞のうち、ニューロンは16,087個、グリアは32,315個。[[UCZQB8EG]]</td><td>1患者の局所組織です。再構成の多くは自動処理で、領域を横断する神経突起は境界で切れます。</td></tr><tr><td>MICrONS, 2025</td><td>1匹のマウス視覚野で活動記録と電子顕微鏡像を対応付け。活動の推定ユニーク数75,909に対し、手動で構造に対応付けたニューロンは15,439個。[[6TNZ57MZ]]</td><td>75,909は複数回の撮影を統合した推定数で、同時記録数でも全数の対応完了でもありません。校正の範囲にも制限があります。</td></tr><tr><td>BANC / MaleCNS, 2026</td><td>それぞれ雌・雄成体の脳と腹側神経索を結ぶ、独立した中枢神経系データ。[[ADD199]][[ADD188]]</td><td>撮像範囲、残る断片、シナプス検出・校正の範囲が異なります。個体固有の全状態や記憶は測っていません。</td></tr></tbody></table></div>{{scopes}}<p>比較では、細胞とニューロン、シナプスの検出と接続先の同定、撮像と人手による校正を分けます。データの版、欠損領域、誤接続の程度を確認してから、モデルの入力に使います。</p>',
      '<div class="tbl"><table><thead><tr><th>Study</th><th>Scope and result</th><th>Boundary of the interpretation</th></tr></thead><tbody><tr><td>Cook et al., 2019</td><td>Whole-animal nervous-system connectomes of hermaphrodite and male <i>C. elegans</i>.[[ADD192]]</td><td>Composite reconstructions combine observations from several animals and some extrapolation, rather than exhaustively measuring one individual.</td></tr><tr><td>Winding et al., 2023</td><td>The brain of one female first-instar fly larva: 3,016 neurons.[[ADD209]]</td><td>The count includes inputs to the brain. It does not cover the complete ventral nerve cord or the adult nervous system.</td></tr><tr><td>FlyWire, 2024</td><td>One adult female fly brain: 139,255 neurons and about 54.5 million chemical synapses between reconstructed neurons.[[ADD196]]</td><td>At a threshold of at least five synapses per directed neuron pair, the graph has 2,700,513 connections among 134,181 neurons. Synapse counts and edge counts differ. The ventral nerve cord, electrical synapses and learning history are outside this reconstruction.</td></tr><tr><td>H01, 2024</td><td>About 1 mm³ of surgically resected human temporal cortex: 57,180 cells, including 16,087 neurons and 32,315 glia.[[UCZQB8EG]]</td><td>Local tissue from one patient, with largely automated reconstruction and neurites truncated at volume boundaries.</td></tr><tr><td>MICrONS, 2025</td><td>Activity and electron microscopy in one mouse\'s visual cortex. The estimated 75,909 unique recorded neurons are distinct from the 15,439 neurons manually matched to EM.[[6TNZ57MZ]]</td><td>The activity count combines several scans; it is neither a simultaneous recording count nor a count of completed structural matches. Proofreading also has restricted coverage.</td></tr><tr><td>BANC / MaleCNS, 2026</td><td>Independent female and male adult central nervous-system resources linking brain and ventral nerve cord.[[ADD199]][[ADD188]]</td><td>Imaging coverage, residual fragments, synapse detection and proofreading differ. Neither measures all individual states or memories.</td></tr></tbody></table></div>{{scopes}}<p>Distinguish cells from neurons, synapse detection from identifying connected partners, and imaging from manual proofreading. Check dataset version, missing regions and reconstruction errors before using a connectome as model input.</p>'),
    s('models',
      '接続図から機能を予測する',
      'Predicting function from connectivity',
      '<p><strong>Shiuら（2024）</strong>は、ハエ脳の接続情報を含む単純な発火モデルから、味覚による摂食開始と触角のグルーミングに関する予測を作り、特定の活性化・抑制実験と照合しました。全脳規模の接続を使うことと、全機能を検証することは別です。<strong>Lappalainenら（2024）</strong>は視覚系の接続数・伝達の符号・運動検出課題を制約にモデルを最適化し、26件の既存研究の神経応答と比較しました。活動記録そのものを学習の教師にはしていませんが、課題情報は使っています。[[V4GV7JAJ]][[XMYSQXY8]]</p><p><strong>CurrierとClandinin（2025）</strong>は、ハエ視葉の実測応答と接続からの予測を比較しました。比較的強い入力が予測情報を多く担う一方、接続の似かよいだけでは詳細な応答を十分説明できませんでした。入力の除外は計算上の操作であり、弱い接続を生物から取り除いてよいという結果ではありません。[[PWIYMZP7]]</p><p><strong>マウス視覚野の基盤モデル</strong>は、多個体の活動から事前学習し、新しい個体の追加記録で調整した後に、新しい種類の視覚刺激への予測を改善しました。接続図からの復元とは異なる方法です。<strong>ZAPBench</strong>は、幼生ゼブラフィッシュ1匹の全脳規模カルシウム活動で、時間と刺激条件を分けた予測比較を行います。論文で評価したモデルは接続図を入力に使っておらず、個体間の汎化試験でもありません。2025年の論文では、活動を記録した同じ個体のEM撮像を終え、接続図を再構成・手動校正中と報告しています。対応付けが完成すれば、同一個体の構造と活動を組み合わせた検証の候補になりますが、接続図の完成や個体特異的な機能再現を実証した結果ではありません。目的の違う評価を組み合わせることが、次の検証を設計する手掛かりになります。[[ADD197]][[FHPYMIG8]]</p>{{fidelity}}',
      '<p><strong>Shiu et al. (2024)</strong> used a simple spiking model containing fly-brain connectivity to predict feeding initiation and antennal grooming, then tested selected activation and silencing predictions experimentally. Brain-wide connectivity does not imply brain-wide functional validation. <strong>Lappalainen et al. (2024)</strong> optimized a visual-system model using connection counts, transmission signs and a motion-estimation task, comparing responses with 26 existing studies. Neural activity was not the training target, but task information was used.[[V4GV7JAJ]][[XMYSQXY8]]</p><p><strong>Currier and Clandinin (2025)</strong> compared measured fly optic-lobe responses with connectivity-based predictions. Relatively strong inputs carried a large share of predictive information, while connectivity similarity did not adequately explain detailed response properties. Removing inputs was a computational analysis, not evidence that weak biological connections can safely be discarded.[[PWIYMZP7]]</p><p>A <strong>mouse visual-cortex foundation model</strong> improved predictions for new stimulus types after pretraining on several animals and adapting to recordings from a new individual. This is distinct from reconstruction using a connectome. <strong>ZAPBench</strong> compares predictions of brain-wide calcium activity from one larval zebrafish using held-out times and stimulus conditions. The models evaluated in the paper do not use a connectome, and the test does not establish cross-individual generalization. The 2025 paper reports completed EM imaging of the same animal used for activity recording, with connectome reconstruction and manual proofreading in progress. Completed correspondence would support testing with paired structure and activity from one individual; the paper does not establish a completed connectome or individual-specific functional reproduction. These different evaluation targets help define complementary experiments.[[ADD197]][[FHPYMIG8]]</p>{{fidelity}}'),
    s('embodiment',
      '身体をつないだモデルの読み方',
      'Interpreting embodied models',
      '<p>BAAIWormは、<i>C. elegans</i>の136ニューロンと身体・環境を閉ループで結び、誘引源へ向かうジグザグ移動を扱うモデルです。全302ニューロン・全行動が対象ではありません。活動相関に合わせた結合の学習と、簡略化した感覚入力・神経から筋への変換を使います。感覚から行動、再び感覚へという循環を検証する一歩です。[[ADD203]]</p><p>Eon Systemsが2026年に公開したハエのデモは、既存の脳モデル・視覚モデル・身体モデルを統合しています。同社の技術説明には、下行ニューロンから運動への対応を人が選んだ点、模倣学習による制御、内部ダイナミクスの検証不足が記載されています。Carboncopiesも「アップロード」と呼ぶための検証不足を指摘しています。ここでは<strong>身体を含むモデル統合</strong>として位置付け、個体の記憶や全内部状態の復元とは区別します。[[EON]][[CCFLY]]</p>',
      "<p>BAAIWorm couples 136 <i>C. elegans</i> neurons with a body and environment to study zigzag movement toward an attractant. It does not cover all 302 neurons or all behaviours. Connections are optimized against activity correlations, with simplified sensory input and a learned neural-to-muscle readout. It is a step toward evaluating the sensation–action feedback loop.[[ADD203]]</p><p>Eon Systems' 2026 fly demonstration integrates existing brain, vision, and body models. Its technical description identifies manually selected descending-neuron mappings, imitation-learned controllers, and missing validation of internal dynamics. Carboncopies also questions whether the evidence warrants the term “upload.” This guide treats the result as <strong>embodied model integration</strong>, distinct from recovery of an individual's memories and complete internal state.[[EON]][[CCFLY]]</p>"),
    s('interfaces',
      '神経インターフェースが示すこと',
      'What neural interfaces demonstrate',
      '<p>神経プロテーゼは、局所の信号と個別学習から実用的な出力を得る研究です。発話の例では、同じ「言葉を出す」システムでも、文字の復号と音声の逐次生成で評価対象が異なります。</p><div class="tbl"><table><thead><tr><th>研究</th><th>示したこと</th><th>条件</th></tr></thead><tbody><tr><td>Willett et al., 2023</td><td>発話を試みる活動から、大語彙の文章を実時間に文字化。[[ADD195]]</td><td>ALSの参加者1名。画面で提示した未学習文を用い、日々の記録・較正を行いました。</td></tr><tr><td>Card et al., 2024</td><td>短い較正から始め、学習を継続して会話利用へ進展。[[ADD204]]</td><td>ALSの参加者1名。初日の30分較正は50語条件で、大語彙には追加学習を行いました。</td></tr><tr><td>Littlejohn et al., 2025</td><td>発話企図から音声と文字を逐次生成。[[ADD202]]</td><td>オンライン実証は脳幹梗塞後の参加者1名。80 msは更新間隔で、一般文の音声開始までの遅延中央値は1.12秒です。</td></tr></tbody></table></div><p>WBEに関連するのは、信号の長期安定性、個人に合わせた推定、閉ループでの出力評価です。これらは発話を試みる局所活動の復号であり、全脳や任意の記憶の読み出しではありません。</p><p>海馬プロテーゼでは、本人のCA3からCA1への活動関係をモデル化し、刺激する8名のうち短期記憶課題は7名、遅延再認課題は6名で評価しました。無刺激・ランダム刺激との比較は、モデルに基づく介入を検証する参考になります。個人の記憶を別の人や機械へ移した研究ではありません。[[JHS9IFXX]]</p>',
      '<p>Neuroprosthetics derive useful outputs from local neural signals and individual training. Speech systems illustrate why decoding text and generating streaming audio need different evaluation measures.</p><div class="tbl"><table><thead><tr><th>Study</th><th>Demonstrated capability</th><th>Conditions</th></tr></thead><tbody><tr><td>Willett et al., 2023</td><td>Real-time, large-vocabulary text decoding from attempted speech.[[ADD195]]</td><td>One participant with ALS; held-out prompted sentences, with daily recordings and calibration.</td></tr><tr><td>Card et al., 2024</td><td>Brief initial calibration followed by continued training and conversational use.[[ADD204]]</td><td>One participant with ALS. The first day\'s 30-minute calibration used a 50-word vocabulary; large-vocabulary use required further training.</td></tr><tr><td>Littlejohn et al., 2025</td><td>Streaming speech and text from attempted speech.[[ADD202]]</td><td>Online demonstration in one participant after brainstem stroke. The 80 ms value is an update interval; median audio-onset latency for general sentences was 1.12 seconds.</td></tr></tbody></table></div><p>The WBE-relevant lessons concern long-term signal stability, individual adaptation and closed-loop output evaluation. These systems decode local activity associated with attempted speech, rather than reading an entire brain or arbitrary memories.</p><p>A hippocampal prosthesis modelled each person\'s CA3-to-CA1 activity and delivered stimulation in eight participants; seven contributed to the short-term memory task and six to delayed recognition. Comparisons with no stimulation and random stimulation provide an example of testing model-based interventions. Memories were not transferred to another person or machine.[[JHS9IFXX]]</p>'),
    s('latest',
      '2026年の情報を読む際の注意点',
      'Reading the 2026 record',
      '<p>BANCの査読論文、MaleCNSの論文・公開データと、Mohintaらによる2026年10月の幼生ハエ中枢神経系の初稿は、資料の段階が異なります。最後の資料はプレプリントで、初齢幼生の中枢神経系を8 nm等方ボクセルで撮像し、自動再構成を提供しています。多くは未校正で、完全に人手校正したのは腹側神経索の24ニューロンです。完成した全接続図として扱わず、再構成・校正法を試す基盤として読む必要があります。[[ADD199]][[ADD188]][[MALEDATA]][[ADD213]]</p><p>この節の論文・データの出版状況は2026年11月4日に確認しました。プレプリントの版、正式出版日、データ更新日は分けて記録します。</p>',
      "<p>The peer-reviewed BANC paper, the MaleCNS paper and dataset, and Mohinta et al.'s October 2026 draft larval fly CNS resource have different publication and reconstruction status. The last is a preprint providing 8 nm isotropic imaging and automated reconstruction of a first-instar CNS. Most reconstruction remains unproofread; 24 ventral nerve cord neurons were completely proofread. Treat it as a resource for testing reconstruction and proofreading, not a completed connectome.[[ADD199]][[ADD188]][[MALEDATA]][[ADD213]]</p><p>Publication and dataset status in this section were checked on 4 November 2026. Record preprint version, formal publication date and dataset updates separately.</p>"),
])

page('carboncopies',
     'Carboncopies Foundationの研究',
     'Carboncopies Foundation research',
     'WBEを測定・同定・検証の課題として進めるための、ロードマップ、開発基盤、ベンチマークを紹介します。',
     'A guide to the roadmap, development platform, and benchmarks for treating WBE as a measurement, identification, and validation problem.', [
    s('mission',
      '現在の研究の柱',
      'Current research pillars',
      '<p>Carboncopies Foundationは、媒体に依存しない心の実現を長期的な目標に掲げ、WBEに必要な研究を支援しています。公式研究ページでは、測定データを実行可能なモデルへ変換する方法と、その結果の検証を重視しています。本サイトはyasufumi-nakataが編集する個人サイトです。Carboncopies Foundationは公開資料の引用元として扱っており、本サイトの発行主体・監修者ではありません。団体による公式見解や承認を表すものではありません。[[CCFAQ]][[CCRESEARCH]]</p>{{carboncopies}}<div class="cards"><article class="card"><h3>Brain Emulation Challenge</h3><p>正解が既知の回路から仮想計測データを作り、復元方法を比較します。</p></article><article class="card"><h3>BrainGenix</h3><p>モデル構築・実行・実験を扱う開発基盤です。製品としての完成や生物のアップロード達成を意味しません。</p></article><article class="card"><h3>WBE Roadmap</h3><p>2008年のロードマップを起点に、技術の更新と必要な研究を継続的に整理しています。</p></article></div>',
      '<p>Carboncopies Foundation supports research toward substrate-independent minds, with WBE as a technical pathway. Its research page emphasizes converting measurements into executable models and validating the results. This is a personal site edited by yasufumi-nakata. Carboncopies Foundation is cited as a source of public material, not presented as the site’s publisher or editorial supervisor. This account does not represent an official statement or endorsement by the Foundation.[[CCFAQ]][[CCRESEARCH]]</p>{{carboncopies}}<div class="cards"><article class="card"><h3>Brain Emulation Challenge</h3><p>Generate virtual measurements from known circuits and compare reconstruction methods.</p></article><article class="card"><h3>BrainGenix</h3><p>A development platform for models, execution, and experiments; its existence does not establish a finished upload system.</p></article><article class="card"><h3>WBE Roadmap</h3><p>An ongoing update of technical requirements and research needs, building on the 2008 roadmap.</p></article></div>'),
    s('challenge',
      'Brain Emulation Challengeの意味',
      'What the Brain Emulation Challenge tests',
      '<p>生物の脳では「本当のパラメーター」をすべて知ることができません。人工的に作った回路なら、正解を保管したまま観測だけを参加者に渡せます。仮想的な構造・活動の計測からモデルを復元し、構造、ダイナミクス、行動・入出力の複数の尺度で比較する設計です。[[CCCHALLENGE]]</p><ol class="plain"><li>正解の回路と課題を固定し、評価データを分離します。</li><li>観測の解像度、ノイズ、欠損、取得費用を変えます。</li><li>複数の復元手法を同じ情報条件で比較します。</li><li>人工回路で有効だった仮定を、生物のデータで別途検証します。</li></ol><p>上の手順は公式構想を踏まえた本サイトの実験設計案です。人工回路での成功は、実際の脳に必要な状態変数がすべて選べたことを保証しません。</p>',
      '<p>We cannot know every true parameter of a biological brain. A synthetic circuit allows ground truth to be retained while participants receive only observations. The Challenge reconstructs models from virtual structural and activity measurements and compares structure, dynamics, and behavioural or input–output performance.[[CCCHALLENGE]]</p><ol class="plain"><li>Fix the ground-truth circuit and task, reserving evaluation data.</li><li>Vary resolution, noise, missingness, and measurement cost.</li><li>Compare reconstruction methods under matched information budgets.</li><li>Test assumptions that worked in synthetic circuits against biological data.</li></ol><p>These steps are this guide\'s experimental design proposal informed by the official concept. Success on synthetic ground truth does not guarantee that every necessary biological state variable was represented.</p>'),
    s('roadmap',
      'ロードマップの公表状況',
      'Roadmap publication status',
      '<p>2026年11月4日の公式ロードマップページでは、忠実度と顕微鏡技術の論文が掲載され、逆問題や概念実証システムは今後の公開項目として案内されています。これは継続中の研究計画です。[[CCROADMAP]]</p><div class="tbl"><table><thead><tr><th>資料</th><th>技術的な要点</th><th>位置付け</th></tr></thead><tbody><tr><td>Linssen &amp; Koene, 2025</td><td>モデルの詳細度や計算費用の選択を、複数階層の機能テストに結び付けます。</td><td>技術評価に関する理論的提案。実現可能性を仮定して議論し、WBEの成功や必要十分な標準検査を実証した論文ではありません。[[XKB4CG64]]</td></tr><tr><td>Collins, Huffman &amp; Koene, 2025</td><td>哺乳類全脳の接続解析に向け、撮像方式・膨張率・保存量などを比較します。</td><td>査読された見通し論文。多数の装置を並列運用する試算を含み、総工程の達成実績や確定費用ではありません。[[EVWH7H32]]</td></tr><tr><td>Inverse Problem / Proof of Concept Systems</td><td>同定と実証系の課題です。</td><td>公式ページ上の今後の項目。[[CCROADMAP]]</td></tr></tbody></table></div>',
      '<p>On 4 November 2026, the official roadmap listed published work on fidelity and microscopy, with inverse problems and proof-of-concept systems listed as upcoming topics. It is an ongoing research programme.[[CCROADMAP]]</p><div class="tbl"><table><thead><tr><th>Source</th><th>Technical contribution</th><th>Status</th></tr></thead><tbody><tr><td>Linssen &amp; Koene, 2025</td><td>Relates model detail and computational cost to functional tests at several levels.</td><td>A theoretical proposal for technical evaluation. It assumes feasibility for its argument; it does not demonstrate successful WBE or a necessary-and-sufficient standard test suite.[[XKB4CG64]]</td></tr><tr><td>Collins, Huffman &amp; Koene, 2025</td><td>Compares imaging, expansion and storage for mammalian whole-brain connectomics.</td><td>A peer-reviewed perspective including hypothetical parallel operation of many instruments, rather than an achieved end-to-end workflow or a firm total cost.[[EVWH7H32]]</td></tr><tr><td>Inverse Problem / Proof of Concept Systems</td><td>Identification and demonstration-system questions.</td><td>Upcoming topics on the official page.[[CCROADMAP]]</td></tr></tbody></table></div>'),
    s('participate',
      '公式資料から研究に参加する',
      'Use the official research resources',
      '<p><a href="https://carboncopies.org/Research/BrainGenix/About/">BrainGenix</a>、<a href="https://carboncopies.org/Research/BrainGenix/Challenge/Overview/">Challenge概要</a>、<a href="https://carboncopies.org/Research/Roadmap/About/">Roadmap</a>を起点に、現在公開されている実験・ソフトウェアの条件を確認してください。利用できる機能や実行環境は更新され得ます。[[CCBRAINGENIX]][[CCCHALLENGE]]</p><p>公開Zoteroライブラリーは、直接WBEを扱う論文に加え、システム同定、神経プロテーゼ、記憶、計測技術をたどる入口になります。本サイトの文献探索もこの一覧を起点の一つにしています。収録されていること自体は、各論文の結論やアップロードの実現可能性を保証しません。[[CCLIBRARY]]</p>',
      '<p>Start with <a href="https://carboncopies.org/Research/BrainGenix/About/">BrainGenix</a>, the <a href="https://carboncopies.org/Research/BrainGenix/Challenge/Overview/">Challenge overview</a>, and the <a href="https://carboncopies.org/Research/Roadmap/About/">roadmap</a>. Check the currently released experiments and software requirements; capabilities and execution environments can change.[[CCBRAINGENIX]][[CCCHALLENGE]]</p><p>The public Zotero library links direct WBE work with system identification, neural prosthetics, memory, and measurement research. It was one starting point for this guide\'s literature search. Inclusion in the library does not itself validate a paper\'s conclusions or the feasibility of uploading.[[CCLIBRARY]]</p>'),
])

page('validation',
     '「再現できた」を検証する',
     'Testing whether an emulation is correct',
     '成功条件を先に決め、学習に使わなかった条件と介入で評価します。見た目の似た行動だけでは、内部の対応は決まりません。',
     'Define success first, then evaluate on held-out conditions and interventions. Similar-looking behaviour alone does not identify the internal mechanism.', [
    s('levels',
      '一つの得点で済ませない',
      'Use more than one score',
      '<p>本サイトでは、以下を<strong>研究設計のチェック項目</strong>として提案します。共通の合格点が定まった認証規格ではありません。対象機能に応じて忠実度を定め、予測の一致と機構の識別を分けて評価します。[[XKB4CG64]][[274IXB72]]</p><div class="table-wrap"><div class="tbl"><table><thead><tr><th>対象</th><th>問い</th><th>評価の例</th></tr></thead><tbody><tr><td>構造</td><td>細胞・接続・型が対応しますか。</td><td>欠損、偽の結合、分割・融合の誤りと、その下流への影響。</td></tr><tr><td>活動</td><td>未知の刺激への応答が対応しますか。</td><td>時系列、状態遷移、時間尺度、繰り返し測定で得る予測上限。</td></tr><tr><td>因果応答</td><td>同じ介入で同じ変化が起こりますか。</td><td>刺激・抑制・切断条件を学習に使わず比較。</td></tr><tr><td>個体特異性</td><td>元の個体を他個体・平均モデルよりよく予測しますか。</td><td>対応付けと計算予算をそろえ、個体差と試行間変動を分離。</td></tr><tr><td>学習・記憶</td><td>その個体が獲得した内容が保持されますか。</td><td>未学習個体、学習内容の異なる個体、保持・再学習・忘却との比較。</td></tr><tr><td>身体・環境</td><td>感覚と運動の循環でも対応しますか。</td><td>身体の制御器を固定した比較、環境・遅延を変えた評価。</td></tr></tbody></table></div></div>{{validation}}',
      '<p>These are proposed research-design checks, not an established certification standard. Define fidelity for the target function and distinguish predictive agreement from identification of mechanisms.[[XKB4CG64]][[274IXB72]]</p><div class="table-wrap"><div class="tbl"><table><thead><tr><th>Target</th><th>Question</th><th>Example evaluation</th></tr></thead><tbody><tr><td>Structure</td><td>Do cells, connections and types correspond?</td><td>Missing or false edges, split/merge errors and downstream effects.</td></tr><tr><td>Activity</td><td>Do responses match for unseen stimuli?</td><td>Time series, state transitions, timescales and a repeat-measurement noise ceiling.</td></tr><tr><td>Causal response</td><td>Does the same intervention produce the same change?</td><td>Stimulation, suppression and lesion conditions excluded from fitting.</td></tr><tr><td>Individual specificity</td><td>Is the original individual predicted better than other-individual or average models?</td><td>Matched registration and computational budgets; separate individual and trial variation.</td></tr><tr><td>Learning and memory</td><td>Is information acquired by that individual retained?</td><td>Untrained and differently trained individuals, retention, relearning and forgetting.</td></tr><tr><td>Embodiment</td><td>Does correspondence survive a sensorimotor loop?</td><td>Fixed body controllers; varied environments and delays.</td></tr></tbody></table></div></div>{{validation}}'),
    s('human-validation',
      '人で取得できる比較データと、主張できる範囲',
      'Human comparison data and the limits of inference',
      '<p>死後の全脳取得を想定する場合、同じ人から生理データを取り直すことはできません。以下は本サイトの計画案です。生前記録を「全脳の正解」とみなさず、実際に測れた観測量にモデルの出力を対応付けます。期間・反復数・領域の一律な必要値は未確立です。試験的な反復記録から信頼性と個体差を見積もり、δ・εを判定できる個体数・セッション数を事前に設計します。</p><div class="table-wrap"><div class="tbl"><table><thead><tr><th>対象</th><th>確保する比較資料の例</th><th>限界と、行わない主張</th></tr></thead><tbody><tr><td>構造</td><td>同一個体の脳画像、取得後の組織の一部を別法で確認した記録、対応付けの誤差。</td><td>粗い画像の一致だけで全シナプスや全分子状態の正しさは認定しません。</td></tr><tr><td>活動</td><td>反復した感覚・認知課題でのEEG/MEG・fMRIなど。臨床目的で得られる頭蓋内記録がある場合はその範囲。</td><td>モデルを同じ計測の観測量へ変換して照合します。集団信号の一致を全細胞の活動一致に置き換えません。</td></tr><tr><td>因果応答</td><td>刺激入力への反応と、適切な審査・同意の下で利用できる刺激・臨床介入記録。</td><td>動物の抑制・切断と同等の介入集合は得られません。観察だけの関連を脳内の因果機構の同定と呼びません。</td></tr><tr><td>個体特異性</td><td>同じ課題を反復した複数セッションと、条件をそろえた複数個体の比較データ。</td><td>領域・細胞型・集団の対応で比較し、測れない個体差や単一例から一般的な識別性能を主張しません。</td></tr><tr><td>学習・記憶</td><td>内容と時点を記録した学習課題、独立した遅延想起・忘却・再学習の評価。</td><td>答えをモデル調整に渡さず評価します。選択した課題の成功を、人生の全記憶の復元へ広げません。</td></tr><tr><td>身体・環境</td><td>感覚帰還・遅延・環境を変えた操作課題と、その入出力記録。</td><td>同じ入出力条件で比較します。限られた模擬身体の一致は元の身体全体の再現を示しません。</td></tr></tbody></table></div></div><p><strong>試料条件を混ぜません。</strong>H01は手術で切除した局所組織、ASCの主要実証は動物の灌流固定を含む条件です。人の死後全脳への適用や、記憶に必要な情報の保持を直接示しません。人への計画では、取得までの経過時間・終末期の状態・固定方法と、どの構造・分子情報の損失を検証したかを記録します。[[UCZQB8EG]][[SDSWEA5J]]</p><p>研究倫理の審査、同意、試料提供の制度は、ここでは制度論としてではなく<strong>データ取得を実行するための前提条件</strong>として扱います。その準備期間を2026〜2035年の記録設計へ組み込み、成立しない比較は2041〜2050年の通過条件から除外せず「未検証」として残します。</p>',
      '<p>When whole-brain acquisition after death is envisaged, physiological recordings cannot subsequently be repeated in the same person. The following is this site\'s proposed design. Prior recordings are not whole-brain ground truth: compare model outputs at the level of the observables actually measured. No universal required duration, repeat count or coverage is established. Use pilot repeated recordings to estimate reliability and individual variation, then plan individuals and sessions that can resolve the prespecified δ and ε.</p><div class="table-wrap"><div class="tbl"><table><thead><tr><th>Target</th><th>Examples of reference data to secure</th><th>Limit and claim withheld</th></tr></thead><tbody><tr><td>Structure</td><td>Same-person brain images, independent checks on sampled acquired tissue, and registration errors.</td><td>Agreement in coarse images does not certify every synapse or molecular state.</td></tr><tr><td>Activity</td><td>Repeated sensory/cognitive tasks with EEG/MEG or fMRI; the available scope of recordings made for clinical purposes.</td><td>Map simulations to the same measured observables. Matching population signals does not establish matching activity in every cell.</td></tr><tr><td>Causal response</td><td>Responses to controlled inputs and stimulation/clinical-intervention records available under appropriate review and consent.</td><td>These do not reproduce the animal suppression/lesion intervention set. Observational associations do not identify internal causal mechanisms.</td></tr><tr><td>Individual specificity</td><td>Multiple repeat sessions and comparable data from multiple individuals.</td><td>Compare at regional, cell-type or population levels. Do not infer unmeasured differences or general identification performance from one case.</td></tr><tr><td>Learning and memory</td><td>Documented learning content/timing plus independent delayed recall, forgetting and relearning tests.</td><td>Withhold test answers from fitting. Success on selected tasks does not establish recovery of all lifetime memories.</td></tr><tr><td>Body and environment</td><td>Input/output records from tasks varying feedback, delay and environment.</td><td>Match input/output conditions. Limited simulated-body agreement does not reproduce the whole original body.</td></tr></tbody></table></div></div><p><strong>Keep acquisition conditions distinct.</strong> H01 used local surgically resected tissue; central ASC demonstrations used conditions including animal perfusion fixation. Neither directly establishes post-mortem human whole-brain applicability or retention of memory-relevant information. A human plan must record acquisition delay, terminal condition and fixation, and specify tested structural/molecular losses.[[UCZQB8EG]][[SDSWEA5J]]</p><p>Research review, consent and sample-provision arrangements are included here as <strong>prerequisites for executable data collection</strong>, without extending the guide into institutional ethics. Include their lead times in the 2026–2035 recording design. An unavailable comparison remains untested at the 2041–2050 gates; it is not silently waived.</p>'),
    s('individual',
      '「その個体」を再現したかを調べる',
      'Test correspondence to that individual',
      '<p>個体Aの測定から作ったモデルを、Aの<strong>未使用の試行</strong>で評価します。同じ評価を、他個体由来のモデル、細胞型ごとの平均接続、活動だけのモデルにも行います。脳領域・細胞型の対応、学習量、計算予算をそろえないと、個体の情報ではなく比較条件の違いを測ってしまいます。</p>{{individual}}<p>Aのモデルが優位でも、それだけで記憶の復元とは言えません。学習済みの内容を評価に使うなら、その答えを追加学習でモデルへ与えない設計が必要です。試行間のばらつきから予測の上限を見積もり、個体差自体が測定可能な大きさかも先に確認します。<strong>未知の個体への汎化</strong>と、<strong>既知の個体を特異的に再現すること</strong>は、別の実験です。</p><p><strong>個体差を測った根拠：</strong>SchlegelらはFlyWireとhemibrainの2個体・3半球を比較しました。強い接続の多くは保存される一方、細胞数や接続重みに差があり、撮像範囲・細胞型の対応・再構成誤差も差に寄与します。3半球を3個体と数えたり、構造の差をそのまま機能の許容幅としたりはしません。[[ISSUE284_SCHLEGEL2024]]</p><p><strong>複数個体での識別行列：</strong>本サイトの提案では、同じ個体の構造と機能評価データが揃う個体を複数用い、行をモデルの由来個体、列を評価対象個体とする成績表を作ります。各個体の未使用データに対して、自分のモデルが他個体モデルよりどれだけよいかを測ります。細胞の対応付けやモデル選択は評価データから独立に固定します。性・発達段階などを揃え、交換可能性が成り立つ層の中で個体ラベルを置換する検定を使います。独立個体が少なく十分な置換ができない場合や、個体差の測定精度が不足する場合は判定を保留します。<a href="/ja/validation.html#protocol">統計手順</a>で検定と必要個体数を定めます。</p><p class="small">この比較設計は本サイトの提案です。掲載論文がこの全手順を達成したという意味ではありません。</p>',
      '<p>Evaluate a model derived from individual A on A\'s held-out trials. Apply the same evaluation to models derived from other individuals, cell-type-average wiring, and activity-only models. Match regional and cell-type correspondence, training data and computational budgets.</p>{{individual}}<p>An advantage for A\'s model is not sufficient evidence of memory reconstruction. Tests of learned content must keep the answers out of additional model training. Estimate a noise ceiling from repeated trials and establish that the relevant individual differences are measurable. Generalising to unseen individuals and specifically reproducing a known individual are different experiments.</p><p><strong>Evidence for individual variation:</strong> Schlegel and colleagues compared FlyWire and hemibrain across two individuals and three hemispheres. Many strong connections were conserved, while cell counts and connection weights varied; coverage, cell-type matching and reconstruction errors also contributed. Three hemispheres are not three individuals, and structural differences do not directly define a functional tolerance.[[ISSUE284_SCHLEGEL2024]]</p><p><strong>An identification matrix across individuals:</strong> our proposed design requires multiple individuals with paired structural and functional evaluation data. Rows identify the individual from which a model was derived; columns identify the individual being predicted. Measure each own-model advantage over other-individual models on held-out data. Fix cell correspondence and model selection independently of the evaluation outcomes. Match sex and developmental stage, and permute individual labels only within strata where exchangeability is defensible. Too few independent individuals for informative permutations, or inadequate precision in measuring individual differences, makes the result inconclusive. The <a href="/validation.html#protocol">statistical procedure</a> specifies the test and sample-size design.</p><p class="small">This comparison is proposed by this site; the cited literature does not demonstrate the entire procedure.</p>'),
    s('benchmarks',
      '実際に使える検証の入口',
      'Practical validation starting points',
      '<p><strong>ZAPBench</strong>は、幼生ゼブラフィッシュの7万超のニューロンの活動記録を基に、全脳規模の活動予測を比較するベンチマークです。観測条件での活動予測を評価するもので、構造の完全回復や記憶の転送を直接認定するものではありません。[[FHPYMIG8]]</p><p><strong>Brain Emulation Challenge</strong>は、人工回路の正解を用いて、観測条件と復元手法の関係を調べます。<strong>MICrONS</strong>は生物学的な構造と機能の対応を調べるデータ基盤になります。三者は目的が異なり、相互に置き換えられません。[[CCCHALLENGE]][[6TNZ57MZ]]</p>',
      '<p><strong>ZAPBench</strong> benchmarks brain-wide activity prediction using recordings of over 70,000 neurons in a larval zebrafish. It measures activity prediction under recorded conditions, not complete structural recovery or memory transfer.[[FHPYMIG8]]</p><p>The <strong>Brain Emulation Challenge</strong> uses synthetic ground truth to examine measurement and reconstruction choices. <strong>MICrONS</strong> supports biological structure–function comparisons. These resources address different questions and are complementary rather than interchangeable.[[CCCHALLENGE]][[6TNZ57MZ]]</p>'),
    s('protocol',
      '比較を成立させる実験手順',
      'A protocol for interpretable comparison',
      '<p>以下は、文献の手法を組み合わせた<strong>本サイトの検証計画案</strong>です。掲載論文が全手順を実施済みという意味ではありません。</p><ol><li><strong>対象・対照・登録項目を固定します。</strong>個体、領域、機能、時間尺度、使用可能な観測、主要指標、独立な実験単位を定めます。単純モデル、接続シャッフル、平均モデル、活動だけのモデルを対照にし、訓練量と計算予算を揃えます。<a href="https://www.cos.io/initiatives/prereg">OSF等への事前登録</a>には、仮説、対応付け、分割、前処理、除外・欠測処理、δ・εと根拠、検定、補正対象、標本数・中止規則、乱数回数、データとコードの版を記載します。既存データでは、すでに見た結果や分析も開示します。</li><li><strong>δとεに対応する判定を定めます。</strong>δは意味のある最小改善量、εは同等と見なす差の許容幅です。課題上の意味と独立した反復測定を根拠に、結果を見る前に定めます。高いほどよい指標の優位性は、差の片側95%信頼下限がδを超えるかで評価します。同等性はTOST（2つの片側検定）を用い、単一主評価で各片側α=.05なら差の90%信頼区間が(−ε,+ε)内に収まることを求めます。通常の差の検定が非有意であるだけでは同等性を示せません。複数の判定では第7項の補正を適用します。[[ISSUE286_LAKENS2017]]</li><li><strong>予測上限と測定精度を確認します。</strong>同条件の反復試行から信号分散と試行変動を分け、予測上限CCmaxと正規化相関CCnormを推定する方法があります。[[ISSUE286_SCHOPPE2016]] 独立な刺激条件への反復応答では、試行変動を補正した近似不偏なr²_ERと、著者のECCIによる区間を用いる方法もあります。固定した刺激集合、応答の独立性、分散安定化などの仮定とSNRを確認します。負の信号分散推定や、区間が[0,1]全体を覆う場合などは、性能判定を保留します。隣接時間ビンの相関したデータにはそのまま適用せず、時間依存を扱う方法の妥当性を別に確かめます。補正値だけでなく、元の単位の絶対誤差と平均的な偏りも報告します。[[ISSUE286_POSPISIL2021]]</li><li><strong>予測対象に合わせてブロック分割します。</strong>同一個体の未来なら連続時間ブロック、別セッションへの予測ならセッション単位、未知の個体への汎化なら個体単位で評価データを確保します。未知の刺激・介入も事前に留保します。前処理やモデル選択の調整は訓練部分内で行い、近接時点の漏れを防ぐ間隔は訓練データの自己相関などから固定します。ブロック化が条件分布を変える場合は、内挿と外挿を区別して報告します。混合モデルを使うだけでは分割の独立性は確保できません。[[ISSUE286_ROBERTS2017]]</li><li><strong>階層と乱数の変動を分けます。</strong>具体案として、モデル条件を固定効果、個体と個体内セッションを変量効果とする混合モデルを用い、試行の残差相関とモデル乱数の変動も明示的に扱います。分布・リンク関数・区間推定法は指標に合わせ、予備データやシミュレーションで被覆率を確かめます。ニューロン、試行、乱数の数を独立個体数として扱いません。この階層モデルの選択は本サイトの提案です。</li><li><strong>個体識別を行列で検定します。</strong>高いほどよい成績Sについて、モデルi・対象個体jのS_ijを作ります。一例として、各対象の自己モデルの成績S_jjから他個体モデルの平均を引き、その差を個体間で平均します。指標の方向、重み、欠測の扱いを先に固定します。帰無仮説下で交換可能な個体の対応ラベルを置換し、同じ個体の反復・条件・乱数の依存関係を保ちます。性・段階と個体が完全に交絡する場合や、可能な置換数が少なすぎる場合は判定を保留します。識別検定の有意性と、差がδを超えることは別々に確認します。</li><li><strong>多重比較を管理します。</strong>主要な機能・課題について、優位性、同等性、識別のどの主張を確認するかと検定集合を事前に固定します。本案ではHolm法で家族内誤り率を.05に管理します。同等性は2つの片側p値の大きい方を一つのTOSTのp値として補正します。未補正の90%区間だけを、多重比較後の合格根拠にはしません。探索的な追加課題は分けて報告し、事前指定した判定の代わりには使いません。</li><li><strong>必要個体数・反復数を設計します。</strong>独立した予備データ等から信号・試行・セッション・個体の分散、自己相関、欠測を見積もります。δ・εに対して複数の真の差とノイズ条件を仮定し、予定する分割、TOST、優位性検定、置換、多重補正を含む全解析をシミュレーションします。例えば検出力80–90%以上と必要な区間幅を満たす独立個体数・セッション数・反復数を選び、仮定への感度を示します。反復数を増やすだけで個体数不足を解決したとは扱いません。独立刺激への応答ではSNRと刺激数・反復数の関係も参考になりますが、刺激への応答を検出する検出力と個体識別・同等性の検出力は別です。[[ISSUE286_LAKENS2017]][[ISSUE286_POSPISIL2021]]</li></ol><p>δやεにWBE全般へ通用する数値は確立していません。生物学的な反復測定がない課題では、探索的なモデル比較として報告し、個体再現の合格判定を行いません。区間、計算費用、再現できなかった条件、追加学習、計画からの変更、データ・コードの版を、否定的な結果とともに残します。</p>',
      '<p>The following is <strong>this site\'s proposed validation plan</strong>, combining methods from the literature. The cited papers do not report completion of this entire procedure.</p><ol><li><strong>Fix the target, controls and registration fields.</strong> Specify individual, region, function, timescale, available observations, primary metric and independent experimental unit. Compare simple, shuffled-connectivity, average and activity-only models under matched training and compute budgets. An <a href="https://www.cos.io/initiatives/prereg">OSF or similar preregistration</a> should record hypotheses, correspondence, splits, preprocessing, exclusions and missing-data handling, δ and ε with their rationale, tests, multiplicity family, sample-size and stopping rules, seed counts, and data/code versions. For existing data, disclose results and analyses already examined.</li><li><strong>Specify decisions for δ and ε.</strong> δ is the minimum meaningful improvement; ε is the tolerated difference for equivalence. Set them before inspecting outcomes, using task relevance and independent repeat measurements. For a higher-is-better metric, assess superiority by whether the one-sided 95% confidence lower bound for the difference exceeds δ. Use TOST, two one-sided tests, for equivalence: for one primary endpoint at α=.05 per one-sided test, the corresponding 90% confidence interval must lie within (−ε,+ε). A nonsignificant conventional difference test does not establish equivalence. Apply step 7 when making multiple decisions.[[ISSUE286_LAKENS2017]]</li><li><strong>Check the noise ceiling and measurement precision.</strong> Repeated trials under matched conditions can separate signal variance from trial variability and estimate CCmax and normalized correlation CCnorm.[[ISSUE286_SCHOPPE2016]] For repeated responses to independent stimulus conditions, another option is approximately unbiased, noise-corrected r²_ER with the authors\' ECCI interval. Check its fixed-stimulus, independence and variance-stabilization assumptions and report SNR. Negative estimated signal variance, or an interval covering all of [0,1], can make performance inconclusive. Do not apply the estimator unchanged to correlated adjacent time bins; separately validate a method that handles temporal dependence. Also report absolute error in the original units and mean bias.[[ISSUE286_POSPISIL2021]]</li><li><strong>Block the split for the prediction target.</strong> Reserve contiguous time blocks for future prediction in the same individual, whole sessions for new-session prediction, and whole individuals for generalization to unseen individuals. Also reserve novel stimuli and interventions in advance. Fit preprocessing and select models within training data; set gaps against nearby-time leakage from training-data autocorrelation or comparable evidence. When blocking changes the condition distribution, distinguish interpolation from extrapolation. A mixed model alone does not make the split independent.[[ISSUE286_ROBERTS2017]]</li><li><strong>Separate hierarchical and random-seed variation.</strong> One proposed analysis uses model condition as a fixed effect and individual and sessions nested within individual as random effects, while explicitly modelling trial residual correlation and variation across model seeds. Choose the distribution, link and interval method for the metric, checking coverage with pilot data or simulations. Do not count neurons, trials or seeds as independent individuals. This particular hierarchical analysis is our proposal.</li><li><strong>Test an individual-identification matrix.</strong> For a higher-is-better score S, form S_ij for model i predicting target individual j. One statistic averages, across targets, the difference between the own-model score S_jj and the mean other-model score. Prespecify score direction, weighting and missing-data handling. Permute model-to-target identity labels only among individuals exchangeable under the null, preserving the dependence among each individual\'s repeats, conditions and seeds. Confounding of identity with sex or stage, or too few possible permutations, makes the test inconclusive. Significance of identification and an effect exceeding δ require separate checks.</li><li><strong>Control multiple comparisons.</strong> Prespecify the family of superiority, equivalence and identification claims across primary functions and tasks. This proposal uses Holm correction to control family-wise error at .05. For equivalence, use the larger of the two one-sided p-values as the p-value for one TOST before correction. An unadjusted 90% interval alone is not evidence of passing a multiplicity-adjusted criterion. Report additional exploratory tasks separately and do not substitute them for the prespecified decisions.</li><li><strong>Design individual and repeat counts.</strong> Estimate signal, trial, session and individual variance, autocorrelation and missingness from independent pilot data or comparable evidence. For the proposed δ and ε, simulate several true-effect and noise scenarios through the complete planned analysis, including splitting, TOST, superiority tests, permutation and multiplicity correction. Choose independent-individual, session and repeat counts to meet, for example, 80–90% power and the required interval width; report sensitivity to assumptions. More repeats do not replace missing independent individuals. SNR-based stimulus/repeat calculations can inform experiments with independent stimulus responses, but power to detect stimulus tuning is distinct from power for individual identification or equivalence.[[ISSUE286_LAKENS2017]][[ISSUE286_POSPISIL2021]]</li></ol><p>No universal numerical δ or ε has been established for WBE. Without biological repeat measurements, report exploratory model comparison rather than a pass for individual emulation. Retain intervals, compute costs, unreproduced conditions, additional fitting, deviations from the plan and data/code versions alongside negative results.</p>'),
    s('negative',
      '失敗も実現への情報になります',
      'Failures also move the research forward',
      '<p>モデルが失敗した条件は、次の測定を選ぶ手掛かりです。伝達強度、受容体、適応、神経修飾などの情報を追加した場合と、既存モデルから除いた場合を比較します。要素どうしの組合せも調べ、追加の順序だけで結論が決まらないようにします。</p><p>追加測定による改善が独立した条件でも再現し、費用に見合うなら、その測定を次の優先項目にします。改善しなければ、測定の質、モデルの形、評価課題の感度を見直します。これは本サイトが提案する反復手順です。</p><p><strong>具体的な追加・省略条件：</strong>接続のみのモデル、受容体・ペプチド情報を追加したモデル、測定可能なグリア状態・調節を加えたモデルを比較します。学習データ量、調整回数、計算予算を揃え、追加自由度だけで有利にならないようにします。分子ラベルを入れ替えた対照と、追加した機構を一つずつ除く対照を置きます。評価は未使用の刺激、想起、介入、時間尺度で行い、改善の区間と追加費用を報告します。これは下記の生物学的知見を動機とした本サイトの設計案で、実施済みの全脳実験ではありません。[[ISSUE283_RANDI2023]][[ISSUE283_WILLIAMSON2025]]</p>',
      '<p>Failure conditions help choose the next measurement. Compare adding information about transmission strength, receptors, adaptation or neuromodulation with removing corresponding components from an existing model. Test selected combinations so that conclusions do not merely reflect the order of additions.</p><p>Prioritise an added measurement when its benefit persists on independent conditions and justifies its cost. Otherwise revisit measurement quality, model form and the sensitivity of the evaluation. This is the iterative procedure proposed by this site.</p><p><strong>Concrete additions and omissions:</strong> Compare a wiring-only model with versions adding receptor/peptide information and measurable glial states or modulation. Match training data, tuning attempts and compute budgets so that extra flexibility alone does not confer an advantage. Include shuffled molecular labels and removal of each added mechanism. Evaluate held-out stimuli, recall, interventions and timescales, reporting uncertainty and added costs. This is a proposed design motivated by the biological findings below, not a completed whole-brain experiment.[[ISSUE283_RANDI2023]][[ISSUE283_WILLIAMSON2025]]</p>'),
])

page('future',
     '研究戦略と展望：何が分かれば次へ進めるか',
     'Research strategy and outlook: evidence for the next step',
     '計測、再構成、同定、計算、検証のどこで誤差と費用が増えるのかを明らかにします。',
     'Identify where errors and costs grow across measurement, reconstruction, identification, computation, and validation.', [
    s('timeline2050', '現在地と年次の目標を先に見る', 'See the current position and planning windows',
      '<p><a href="/ja/history.html#dashboard">6領域の進捗と12課題</a>、<a href="/ja/history.html#roadmap2050">2050年の必要条件を点検する五つの段階</a>を歴史ページにまとめています。このページでは、その前半を支えるM1〜M4の実験条件と、計算量の見積もりを詳しく説明します。</p>',
      '<p>The history page brings together <a href="/history.html#dashboard">six domains and 12 open tasks</a> and <a href="/history.html#roadmap2050">five stages for testing the conditions required by 2050</a>. This page explains the M1–M4 tests underlying the early stages and how to estimate computational scale.</p>'),
    s('gates',
      '四つの里程標と、通過の判定',
      'Four milestones and decision rules',
      '<p>長期的な目標を、検証可能な里程標へ分けます。以下は本サイトの研究戦略案です。2008年のロードマップ、最新の総説、Carboncopiesの更新計画を参照しつつ、達成の判定は個別の実験に置きます。[[9B7EMU3K]][[REPORTFINAL]][[CCROADMAP]]</p>{{roadmap}}<div class="table-wrap"><div class="tbl"><table><thead><tr><th>里程標</th><th>必要な比較と成果物</th><th>次へ進む判定</th><th>現在の根拠</th></tr></thead><tbody><tr><td>M1：復元手法を検査する</td><td>正解既知の人工回路で、点推定と近似事後分布を比較。観測の種類・数、欠測、ノイズに対し、復元誤差、事後区間の被覆率、事前分布と乱数への感度、未使用刺激・介入への事後予測を公開。</td><td>分布の狭さだけでなく、未知の回路・介入で事前基準を満たし、誤った確信やモデル不適合を検出。別実装でも再現。</td><td>人工モデルの同定研究、神経動態モデルの近似事後推定、Challengeの枠組みが出発点です。ここに掲げた評価全体は本サイトの提案です。[[274IXB72]][[ISSUE285_GONCALVES2020]][[CCCHALLENGE]]</td></tr><tr><td>M2：接続図に必要な精度を絞る</td><td>ハエなどの公開モデルで、欠損・誤結合と予測の変化を比較。</td><td>元の結果を再現し、事前の許容幅内に予測を保つ誤差範囲を、第2のモデルでも確認。</td><td>接続に基づく予測は報告済みです。共通の許容誤差は未確定です。[[V4GV7JAJ]][[XMYSQXY8]]</td></tr><tr><td>M3：元の個体との対応を示す</td><td>複数個体の各々で構造・活動・介入を対応付け、他個体・平均モデルと識別行列で比較。哺乳類では一対一のニューロン対応を前提とせず、細胞型・領域・集団表現の対応を評価データから独立に固定。</td><td>未知の介入における自己個体モデルの優位性がδを超え、測定誤差と階層的な変動を含む区間・検定で確認できること。少数個体や交絡で識別不能なら保留。</td><td>MICrONSは構造・活動対応、ハエの複数接続図比較は構造変動の根拠です。ZAPBenchでは同じ個体の接続図再構成が進行中と報告されています。いずれもM3全体の達成ではありません。[[6TNZ57MZ]][[ISSUE284_SCHLEGEL2024]][[FHPYMIG8]]</td></tr><tr><td>M4：学習済みの情報を評価する</td><td>学習内容の異なる個体と対照個体で、復元後の独立した想起課題を比較。</td><td>答えの追加学習なしで、保持・忘却・再学習の個体差が事前の許容幅で対応。</td><td>本サイトの文献範囲では未達成です。エングラム研究は必要な測定を考える手掛かりです。[[LP5F3H2Q]]</td></tr></tbody></table></div></div><p>δと許容幅の決め方は<a href="/ja/validation.html#protocol">検証手順</a>を参照してください。M4も単独で全脳エミュレーションの完成を認定する条件ではなく、個体の記憶について主張するための検証課題です。</p>',
      '<p>Break the long-term goal into testable milestones. The following is this site\'s proposed strategy, informed by the 2008 roadmap, a recent technical review and Carboncopies\' update programme; decisions belong to individual experiments.[[9B7EMU3K]][[REPORTFINAL]][[CCROADMAP]]</p>{{roadmap}}<div class="table-wrap"><div class="tbl"><table><thead><tr><th>Milestone</th><th>Required comparison and output</th><th>Decision to advance</th><th>Present evidence</th></tr></thead><tbody><tr><td>M1: audit reconstruction methods</td><td>Compare point estimates with approximate posteriors in artificial circuits with known truth. Vary observation type/count, missingness and noise; report reconstruction error, posterior-interval coverage, prior/seed sensitivity and posterior predictions under held-out stimuli and interventions.</td><td>Meet prespecified criteria on unseen circuits and interventions, detect false certainty or model mismatch, and replicate in another implementation. Posterior concentration alone is insufficient.</td><td>Artificial-model identification studies, approximate posterior inference for neural dynamics and the Challenge provide starting points. This combined evaluation remains our proposal.[[274IXB72]][[ISSUE285_GONCALVES2020]][[CCCHALLENGE]]</td></tr><tr><td>M2: bound required wiring accuracy</td><td>Public models, such as fly models; vary missing/false connections and measure prediction changes.</td><td>Reproduce the original result and confirm an error range that preserves predictions within a prespecified tolerance in a second model.</td><td>Connectome-based predictions exist; a shared error tolerance is not established.[[V4GV7JAJ]][[XMYSQXY8]]</td></tr><tr><td>M3: establish individual correspondence</td><td>Pair structure, activity and interventions in multiple individuals; compare other-individual and average models in an identification matrix. For mammals, prespecify cell-type, regional or population correspondence independently of test data, without assuming one-to-one neuronal matches.</td><td>Confirm an own-individual advantage exceeding δ on unseen interventions with intervals/tests accounting for measurement error and hierarchical variation. Too few individuals or unresolved confounding makes identification inconclusive.</td><td>MICrONS supports structure–activity pairing; fly multi-connectome comparisons document structural variation. ZAPBench reports reconstruction in progress for the same animal used for activity recording. None establishes all of M3.[[6TNZ57MZ]][[ISSUE284_SCHLEGEL2024]][[FHPYMIG8]]</td></tr><tr><td>M4: test previously learned information</td><td>Differently trained and control individuals; independent recall after reconstruction.</td><td>Prespecified correspondence in retention, forgetting and relearning without training the model on the test answers.</td><td>Unachieved in this review\'s scope. Engram research helps identify candidate measurements.[[LP5F3H2Q]]</td></tr></tbody></table></div></div><p>See the <a href="/validation.html#protocol">validation protocol</a> for setting δ and tolerances. M4 alone would not certify completed WBE; it addresses claims about an individual\'s memory.</p>'),
    s('assumptions',
      '成否によって方針を変える',
      'Change direction when evidence changes',
      '<p><strong>作業仮説：</strong>固定後にも残る構造・分子情報に、再現したい長期記憶や個体差に十分な情報が含まれるかを検証します。この十分性は、構造保存の成功や研究者の見解だけでは確立しません。[[SDSWEA5J]][[ADD210]]</p><ul><li>構造だけでは介入の予測が足りない場合は、機能記録や分子情報を追加し、改善を測ります。</li><li>個体固有の接続を使っても平均モデルを上回らない場合は、課題の感度とモデルの形を検査します。一般的な機能について平均情報で足りる可能性も結果として残します。</li><li>人工回路で通用した方法が生物で崩れる場合は、仮想データの仮定を見直します。</li></ul><p>人工回路と小型動物・局所回路を往復し、同じ検証がより広い領域で維持されるかを調べます。種を並べた順番を、そのまま人への成功保証や実現年へ変換しません。</p>',
      '<p><strong>Working hypothesis:</strong> test whether structure and molecular information surviving fixation retain enough information about the long-term memories and individual differences of interest. Preserved anatomy and expert opinion do not establish sufficiency.[[SDSWEA5J]][[ADD210]]</p><ul><li>If structure alone fails on intervention predictions, add functional or molecular observations and measure the benefit.</li><li>If individual wiring does not outperform an average model, inspect task sensitivity and model form. Report the possibility that average information is sufficient for the tested generic function.</li><li>If a method succeeds on artificial circuits but fails on biology, revise the synthetic-data assumptions.</li></ul><p>Iterate between artificial circuits, small animals and local circuits, then test whether correspondence survives greater anatomical coverage. A sequence of species is not a guarantee or a timetable for human WBE.</p>'),
    s('scaling',
      '撮像と計算の量を試算する',
      'Explore imaging and computation scale',
      '<p>撮像量と計算量を分けて考えます。下の計算機では異方的なボクセルも指定できます。たとえば1 mm³、10×10×10 nm、1 byte/voxelなら無圧縮画像は1 PBです。これは幾何学的な例であり、必要な解像度や実際の保存量を推定した値ではありません。</p><p>圧縮、索引、通信、冗長保存、前処理、校正、学習、細胞内の区画計算は含みません。実費を見積もるときは撮像方式と試料条件ごとの値を確認します。[[EVWH7H32]]</p>{{calculator}}' + acquisition_calculator('ja'),
      '<p>Separate imaging volume from simulation cost. The calculator accepts anisotropic voxels. For example, 1 mm³ at 10×10×10 nm and one byte per voxel gives 1 PB of raw images. This is a geometric example, not an estimate of required resolution or actual stored data.</p><p>Compression, indexing, communication, redundancy, preprocessing, proofreading, training and intracellular compartment calculations are excluded. Cost estimates require method- and sample-specific measurements.[[EVWH7H32]]</p>{{calculator}}' + acquisition_calculator('en')),
    s('bottlenecks',
      '計算機が速くなっても残る問題',
      'What faster computers do not solve',
      '<p>計算資源は必要条件の一つですが、必要な状態を測れていなければ、速い計算機でもその情報は復元できません。画像の分割、細胞の対応付け、パラメーターの識別可能性、学習則、検証用データが連続した課題になります。[[EVWH7H32]][[XKB4CG64]][[274IXB72]]</p><p>単一の実現年を示すより、どの実証がいつ可能になったかを更新する方が研究を進めやすくなります。特に、人への外挿では、種、領域、学習履歴、記録できる時間尺度の違いを明示してください。</p>',
      '<p>Compute is one requirement. Faster hardware cannot recover unmeasured information simply by running longer. Segmentation, registration, parameter identifiability, learning rules, and independent evaluation data remain linked challenges.[[EVWH7H32]][[XKB4CG64]][[274IXB72]]</p><p>Tracking demonstrated capabilities is more useful for research planning than assigning one arrival date. Extrapolation to humans must state differences in species, region, learning history, and observable timescales.</p>'),
])

page('action',
     '最初の研究課題：接続図の誤差と機能予測',
     'First project: wiring errors and functional prediction',
     '公開データと再現可能な評価から、必要な情報と不足している情報を一つずつ絞ります。',
     'Use public data and reproducible tests to determine which information is necessary and what remains missing.', [
    s('projects',
      'まず一つの予測を再現し、必要な接続精度を調べる',
      'Reproduce one prediction, then test required wiring accuracy',
      '<p><strong>優先する課題：</strong>公開されたハエの接続図モデルで、接続の欠損や誤りが、実験で検証された予測をどこまで変えるかを調べます。最初は一つの感覚運動課題と小さな回路に範囲を絞り、原論文の再現から始めます。Shiuらのモデルを候補にし、別のモデルでの確認にはLappalainenらの視覚モデルを検討できます。[[V4GV7JAJ]][[XMYSQXY8]]</p><p class="small">以下は本サイトの実験計画案です。ここで比較実験を実施したという報告ではありません。</p><div class="table-wrap"><div class="tbl"><table><thead><tr><th>条件</th><th>比較する内容</th><th>分かること</th></tr></thead><tbody><tr><td>C0：原論文の条件</td><td>接続図、前処理、入力、モデルの版を固定して再現。</td><td>後の変更を比較できる基準。</td></tr><tr><td>C1：制御した誤差</td><td>欠損、偽の結合、細胞の分割・融合を個別に、次に組み合わせて追加。</td><td>どの誤差がどの予測を壊すか。</td></tr><tr><td>C2：平均的な接続</td><td>細胞型ごとの平均に置き換え、重みの扱いをそろえる。細胞型の定義と版を固定し、複数接続図の対応を利用する場合はその出典を記録する。[[ISSUE284_SCHLEGEL2024]]</td><td>細胞型の情報を超える接続の寄与。</td></tr><tr><td>C3：シャッフル</td><td>次数を保つ対照と細胞型を保つ対照を別々に作る。</td><td>接続のどの性質が予測に必要か。</td></tr><tr><td>C4：反復測定と複数個体の接続図</td><td>利用可能な反復測定を比較し、FlyWire、BANCの脳部分、MaleCNS、hemibrainで共通する領域・細胞型・入出力を事前に選ぶ。同じモデル規則と課題で予測の変化を測る。</td><td>測定の変動と、異なる接続図に対するモデル予測の変動。機能データがなければ個体特異性は判定しない。</td></tr></tbody></table></div></div><p>左右差は個体内の対照として使えますが、個体差の代わりにはなりません。同じ個体の構造・活動データがない段階では、結果を<strong>接続図モデルの頑健性</strong>として報告します。</p><p><strong>C4の対応付けと交絡：</strong>SchlegelらのFlyWire・hemibrain比較を、細胞型の対応と構造変動を考える根拠にします。BANC・MaleCNSを含む比較では、共通領域外からの入力の扱い、性、発達段階、細胞数、撮像範囲、データ版、再構成の完備性、伝達物質推定、対応の不確実性を記録します。対応できない細胞型は事前規則で除外し、各要因を変える感度解析を添えます。4つの接続図を同質な反復標本とは扱いません。[[ISSUE284_SCHLEGEL2024]][[ADD196]][[ADD199]][[ADD188]]</p><p><strong>先行研究との関係：</strong>細胞型と構造を比較した先行研究を出発点に、ここでは共通のモデル規則・入力・評価指標の下で予測変動を測ることを提案します。構造やモデル予測の変動はδ・εを検討する参考資料に留め、機能の反復測定誤差と課題上意味のある差から許容幅を別に定めます。<a href="/ja/validation.html#protocol">具体的な統計手順</a>を使い、既存の感度解析に対する新規性も実験前に確認します。</p>',
      '<p><strong>Priority project:</strong> use a public fly connectome model to test how wiring errors change predictions that were experimentally validated. Begin with one sensorimotor task and a small circuit, reproducing the original study first. Shiu and colleagues\' model is a candidate; Lappalainen and colleagues\' visual model offers a possible independent modelling framework.[[V4GV7JAJ]][[XMYSQXY8]]</p><p class="small">This is a proposed experiment, not a report of comparisons performed here.</p><div class="table-wrap"><div class="tbl"><table><thead><tr><th>Condition</th><th>Comparison</th><th>Question answered</th></tr></thead><tbody><tr><td>C0: original setting</td><td>Fix connectome, preprocessing, inputs and model version; reproduce the result.</td><td>Establish a baseline.</td></tr><tr><td>C1: controlled errors</td><td>Add missing edges, false edges and split/merge errors separately, then in combinations.</td><td>Which errors disrupt which predictions?</td></tr><tr><td>C2: average wiring</td><td>Replace connections with cell-type averages under matched weight handling. Fix cell-type definitions and versions; record the source when using cross-connectome type correspondence.[[ISSUE284_SCHLEGEL2024]]</td><td>What does wiring contribute beyond cell type?</td></tr><tr><td>C3: shuffled wiring</td><td>Use separate degree-preserving and type-preserving controls.</td><td>Which connectivity properties matter?</td></tr><tr><td>C4: repeat measurements and multiple connectomes</td><td>Compare available repeated measurements and prespecify common regions, cell types and inputs/outputs across FlyWire, the brain portion of BANC, MaleCNS and hemibrain. Measure prediction changes under the same model rules and task.</td><td>Measurement variation and model sensitivity across connectomes. Without paired functional data, individual specificity remains untested.</td></tr></tbody></table></div></div><p>Left–right differences are within-individual controls, not substitutes for individual variation. Without paired structure and activity from the same individual, report connectome-model robustness rather than individual emulation.</p><p><strong>Correspondence and confounds in C4:</strong> Schlegel and colleagues provide evidence on cell-type matching and structural variation between FlyWire and hemibrain. Comparisons including BANC and MaleCNS must document treatment of inputs outside shared regions, sex, developmental stage, cell counts, coverage, data versions, reconstruction completeness, transmitter predictions and matching uncertainty. Exclude unmatched types by prespecified rules and vary these factors in sensitivity analyses. Do not treat the four connectomes as homogeneous biological replicates.[[ISSUE284_SCHLEGEL2024]][[ADD196]][[ADD199]][[ADD188]]</p><p><strong>Relationship to prior work:</strong> building on comparisons of cell types and structure, we propose measuring prediction changes under common model rules, inputs and metrics. Structural or simulated variability can inform margin selection but does not determine δ or ε: use functional repeatability and task-relevant differences to define those separately. Follow the <a href="/validation.html#protocol">statistical procedure</a> and establish the contribution beyond existing sensitivity analyses before running the experiment.</p>'),
    s('workflow',
      '準備・完了・成功を分けて決める',
      'Separate preparation, completion and success',
      '<ol><li><strong>準備：</strong>データ・コードの版と利用条件、対象回路、再現する図・表、入力を記録します。完全な再実行に必要なデータが揃わなければ、範囲を絞ります。</li><li><strong>小さな試行：</strong>メモリー、実行時間、保存量を測り、全条件と複数の乱数を実行できる予算を決めます。文献の規模から所要時間を断定しません。</li><li><strong>事前の判定：</strong>評価指標、許容幅、最小差、誤差を加える範囲、乱数数、方針を見直す日を決めます。</li><li><strong>完了条件：</strong>C0の再現とC1〜C4の実施可能な比較を、否定的な結果も含めて公開します。実施できなかった比較を明示します。</li><li><strong>成功条件：</strong>C0が適切な対照を事前の最小差以上で上回り、許容幅内に予測を保つ誤差範囲が別のモデルでも確認できます。生物学的な許容幅が未設定なら、暫定の感度分析に留めます。</li></ol><p>C0を再現できない場合は、版や前処理の差を調べたうえで再現性の問題として報告します。どの誤差でも得点が変わらない場合は評価の感度を、小さな誤差で崩れる場合はモデルの不安定さを先に検査します。</p>',
      '<ol><li><strong>Prepare:</strong> record data/code versions, reuse terms, circuit scope, the target figure or table and inputs. Narrow the experiment if required data are unavailable.</li><li><strong>Pilot:</strong> measure memory, runtime and storage; budget all conditions and multiple seeds. Do not infer runtime from paper scale alone.</li><li><strong>Prespecify decisions:</strong> choose the metric, tolerance, minimum effect, error range, seeds and a date for reviewing the approach.</li><li><strong>Completion:</strong> publish C0 reproduction and feasible C1–C4 comparisons, including negative results. Identify comparisons that could not be performed.</li><li><strong>Success:</strong> C0 exceeds suitable controls by a prespecified meaningful difference, and a prediction-preserving error range is confirmed in another model. Without a biological tolerance, label the result a provisional sensitivity analysis.</li></ol><p>If C0 cannot be reproduced, investigate versions and preprocessing before reporting a reproducibility problem. If scores never change, examine metric sensitivity; if tiny errors collapse performance, investigate model instability first.</p>'),
    s('next',
      '次の課題と、使える基盤',
      'Follow-up projects and supporting tools',
      '<p>最初の課題で必要な精度を絞った後は、人工回路で測定条件を選ぶ研究、ZAPBenchで未知の活動を予測する研究、同じ個体の構造・機能を結ぶ研究へ展開できます。測りたい問いに合う基盤を選びます。[[CCCHALLENGE]][[FHPYMIG8]][[6TNZ57MZ]]</p><p>NEURONは細胞・回路のシミュレーション、Brain Modeling ToolKitは複数の詳細度を扱うモデル構築、SpiNNakerは多数のスパイクを通信する計算アーキテクチャの参考になります。各論文が評価した範囲と現在のソフトウェアの機能を混同せず、実行前に利用する版を確認します。[[Q8SGY2SV]][[9DXWPDVH]][[ADD206]]</p>',
      '<p>After bounding required accuracy, follow-up projects can examine measurement choice in known artificial circuits, held-out activity prediction in ZAPBench, and paired structure–function measurements. Choose a platform for the question.[[CCCHALLENGE]][[FHPYMIG8]][[6TNZ57MZ]]</p><p>NEURON supports cellular and circuit simulation; the Brain Modeling ToolKit supports multiple modelling scales; SpiNNaker provides a reference architecture for communicating large numbers of spikes. Distinguish what the papers evaluated from the capabilities of the software version used in a new experiment.[[Q8SGY2SV]][[9DXWPDVH]][[ADD206]]</p>'),
    s('skills',
      '専門ごとの参加口',
      'Where different skills contribute',
      '<p><strong>実験神経科学：</strong>構造と活動の対応、介入、長期記録。<strong>顕微鏡・画像処理：</strong>取得速度、変形補正、分割と校正。<strong>数理・機械学習：</strong>逆問題、識別可能性、不確実性、一般化。<strong>計算基盤：</strong>メモリー、分散実行、再現性。<strong>資料整理：</strong>DOI、版、訂正、データとコードの対応を保つことです。</p><p>「脳を丸ごと動かす」という目標を、検証可能な小さな成果物につなげることが、実現に向けた作業になります。</p>',
      '<p><strong>Experimental neuroscience:</strong> structure–activity registration, interventions, longitudinal recordings. <strong>Microscopy and image analysis:</strong> throughput, deformation correction, segmentation, proofreading. <strong>Mathematics and machine learning:</strong> inverse problems, identifiability, uncertainty, generalization. <strong>Computing:</strong> memory, distributed execution, reproducibility. <strong>Literature curation:</strong> maintain links among DOI, version, corrections, data, and code.</p><p>Turn the ambition of running a brain into small, falsifiable deliverables that resolve a necessary part of the problem.</p>'),
])

page('history',
     '歴史と現在地：2050年までに何を越えるか',
     'History and current progress: the gates to 2050',
     'できたこと、残る主要課題、次へ進む条件を一つの画面からたどります。2050年を技術的な完成目標に置いた、条件付きの研究計画です。',
     'See what works, what remains, and the evidence needed to advance. A conditional research plan targeting technical completion in 2050.', [
    s('overview', '現在地を一目で', 'The current position at a glance',
      '<div class="dashboard-totals"><p><strong>6</strong>研究領域を点検</p><p><strong>12</strong>主要な未解決課題</p><p><strong>5</strong>2050年までの判定点</p></div><div class="key"><p><strong>現在地：</strong>小型動物の接続図、哺乳類の局所的な構造・活動対応、限定された機能の予測まで進んでいます。次に必要なのは、これらを同じ個体でつなぎ、学習済みの情報を保持する再現を検証することです。[[ADD196]][[6TNZ57MZ]][[V4GV7JAJ]][[XMYSQXY8]]</p><p><strong>最大の未解決：</strong>どの情報をどの精度で取得すれば、元の個体の機能と記憶を再現するのに十分なのか。確認した文献では、人の個体固有の記憶を保持する全脳再現は未実証です。[[XKB4CG64]][[REPORTFINAL]]</p></div><p class="small">6領域と12課題は本サイトの整理です。課題の数は研究量や成功確率を表しません。構成の更新日：{{edition_date}}。資料ごとの確認日は文献一覧に記載します。</p>',
      '<div class="dashboard-totals"><p><strong>6</strong>research domains</p><p><strong>12</strong>major open tasks</p><p><strong>5</strong>review gates to 2050</p></div><div class="key"><p><strong>Current position:</strong> small-animal wiring maps, local mammalian structure–activity pairing, and predictions of limited functions. The next step is to connect these in the same individual and test reproduction that retains previously learned information.[[ADD196]][[6TNZ57MZ]][[V4GV7JAJ]][[XMYSQXY8]]</p><p><strong>The central gap:</strong> what information, measured at what precision, is sufficient to recover an individual’s functions and memories? The reviewed literature does not demonstrate human whole-brain reproduction retaining individual memories.[[XKB4CG64]][[REPORTFINAL]]</p></div><p class="small">The six domains and 12 tasks are this site’s organisation of the problem. Task counts do not measure research effort or probability of success. Organisation updated: {{edition_date}}. Individual source access dates are recorded in the library.</p>'),
    s('dashboard', '6領域の到達点と、残る12課題', 'Six domains and 12 remaining tasks',
      '<p>上段にできたこと、下段に次の壁を示します。各カードを開くと、次に実証する主要課題を確認できます。課題は並行して研究し、測定とモデルの結果を互いに返します。</p>' + status_grid('ja', detail=True),
      '<p>Each card shows demonstrated capabilities and the next barrier. Expand it for the major tasks that still need evidence. Work proceeds in parallel, with measurements and models informing each other.</p>' + status_grid('en', detail=True)),
    s('roadmap2050', '2050年の仮定を点検する、五つの段階', 'Five stages for testing a 2050 scenario',
      '<p><strong>以下の年は、本サイトが提案する点検時期です。</strong>文献から得た完成予測や、Carboncopies Foundationの公式日程ではありません。前段階の条件が満たされなければ、後段階の日程も変更します。研究の開始年ではなく、成果を判定する節目を示しています。</p>' + horizon('ja', detail=True) + '<p>2030・2035年の段階は、<a href="/ja/future.html#gates">M1〜M4の検証課題</a>に対応します。後半はそれを大規模化し、人へ適用できる条件を検査する本サイトの提案です。小型動物での成功だけで、人でも成立すると判定しません。</p><p><strong>長期の準備は並行して進めます。</strong>本案では2026〜2030年に、人で必要な比較データと継続記録の設計を始め、2031〜2035年に実施可能な範囲の記録・追試の体制を整えます。速度・費用は2030年から見直します。生体から全脳情報を取得できると仮定した計画ではありません。</p><p>土台にしているのは、走査・解釈・シミュレーションを分けた2008年ロードマップと、現在の機能評価・測定研究です。これらの文献が、上記の年表を保証しているわけではありません。[[9B7EMU3K]][[XKB4CG64]][[EVWH7H32]]</p>',
      '<p><strong>These are proposed target windows set by this site.</strong> They are not completion forecasts derived from the literature or Carboncopies Foundation’s official schedule. If an earlier gate remains unmet, later dates change. Windows mark reviews of achieved capabilities, not the first year work begins.</p>' + horizon('en', detail=True) + '<p>The 2030 and 2035 stages correspond to <a href="/future.html#gates">M1–M4</a>. Later stages propose scaling those tests and establishing conditions for human application. Success in a small animal alone does not establish transfer to humans.</p><p><strong>Long-lead preparations run in parallel.</strong> This proposal starts designing human comparison data and longitudinal recordings in 2026–2030, then establishes feasible recording and replication arrangements in 2031–2035. Throughput and cost are reviewed from 2030 onward. This does not assume that all necessary whole-brain information can be acquired in a living person.</p><p>The technical foundation is the 2008 roadmap’s separation of scanning, interpretation and simulation, together with current measurement and fidelity research. These sources do not establish the dates above.[[9B7EMU3K]][[XKB4CG64]][[EVWH7H32]]</p>'),
    s('quantitative-conditions',
      '2050年へ進むための定量条件',
      'Quantitative conditions for a 2050 scenario',
      '<p><strong>年次は編集上の点検時期です。</strong>2030・2035・2040・2045・2050年という等間隔は、依存する研究を見直すための便宜的な区切りで、成長率や成功確率から計算した日程ではありません。条件を満たす場合は次の統合を検討し、満たさない場合は工程と日程を延長します。早期・中期には測定誤差と個体差の根拠を集め、後期の必要速度を実測と比較します。</p><p>Collinsら（2025）の表3は、装置費1億米ドル相当で人の脳を撮像する時間を、ExLSFM（333台）で約34年、EM（200台）で約1,667年と試算しています。前者は有効ボクセル12.4×12.4×30 nm、後者は3.6×3.6×45 nmで、同じ解像度の比較ではありません。EM速度は投影値、ExLSFMは拡大法との仮想的な組合せを含み、全脳で実証した運転実績ではありません。[[EVWH7H32]]</p><div class="table-wrap"><div class="tbl"><table><thead><tr><th>撮像だけに割り当てる時間</th><th>ExLSFMに必要な総取得速度</th><th>EMに必要な総取得速度</th></tr></thead><tbody><tr><td>5年</td><td>約6.8倍（34÷5）</td><td>約333.4倍（1,667÷5）</td></tr><tr><td>2年</td><td>約17倍（34÷2）</td><td>約833.5倍（1,667÷2）</td></tr></tbody></table></div></div><p class="small">倍率は表3の丸め値を割った本サイトの算術で、技術進歩の予測ではありません。台数と1台当たり速度の積に必要な倍率を表します。同じ台数を保つなら1台当たり速度が、同じ速度を保つなら台数が、それだけ増える必要があります。調達・建設・運転費まで線形に増えるとは仮定しません。</p><p>2046〜2050年の全期間を撮像に使えば、準備・再構成・校正・モデル化・独立検証の時間は残りません。工程は並行化の可否も含めて別々に見積もり、最も遅い工程と依存関係で全体の所要時間を判定します。マウス段階も、自動追跡・校正が必要精度を満たすことを通過条件にします。撮像年数は<a href="/ja/future.html#scaling">台数と速度の計算機</a>で変更できます。[[EVWH7H32]]</p>',
      '<p><strong>The years are editorial review windows.</strong> The five-year spacing from 2030 to 2050 is a convenient cadence for revisiting dependent work, not a schedule calculated from growth rates or success probabilities. Meeting a gate permits consideration of the next integration; missing it extends both the workflow and timetable. Early stages establish measurement-error and individual-difference evidence before comparing measured throughput with later requirements.</p><p>Collins et al. (2025), Table 3, estimate human-brain imaging at about 34 years with 333 ExLSFM instruments or 1,667 years with 200 EM instruments, each representing US$100 million of instruments. Effective voxel sizes differ: 12.4×12.4×30 nm versus 3.6×3.6×45 nm. EM uses projected throughput; ExLSFM includes a hypothetical combination with expansion. Neither is demonstrated whole-brain operation.[[EVWH7H32]]</p><div class="table-wrap"><div class="tbl"><table><thead><tr><th>Time for imaging alone</th><th>Required ExLSFM aggregate rate</th><th>Required EM aggregate rate</th></tr></thead><tbody><tr><td>5 years</td><td>About 6.8× (34/5)</td><td>About 333.4× (1,667/5)</td></tr><tr><td>2 years</td><td>About 17× (34/2)</td><td>About 833.5× (1,667/2)</td></tr></tbody></table></div></div><p class="small">These are this site\'s arithmetic from rounded table values, not forecasts of technological progress. They scale the product of instrument count and per-instrument throughput. Keeping one fixed requires increasing the other by that factor. Procurement, construction and operating cost are not assumed to scale linearly.</p><p>Using all of 2046–2050 for imaging leaves no time for preparation, reconstruction, correction, modelling or independent validation. Budget each separately, specifying possible overlap and workflow dependencies. The mouse gate also requires automated tracing/correction at adequate accuracy. Change instrument counts and rates in the <a href="/future.html#scaling">acquisition calculator</a>.[[EVWH7H32]]</p>'),
    s('target', '条件付きで目指す統合検証とは', 'What the conditional integration target means',
      '<p>目標は、<strong>特定の人の脳の測定情報に基づく全脳モデルが、事前に定めた機能・時間尺度で、その人の活動、学習済み情報、学習能力、身体との相互作用に対応すること</strong>です。これは技術的な研究目標であり、あらゆる状況を完全に再現したという認定ではありません。個体の記憶と技能を含める考え方は2008年ロードマップ、用途ごとの機能検証は忠実度研究を参照しています。[[9B7EMU3K]][[XKB4CG64]]</p><ul><li><strong>測定から復元まで：</strong>どの個体のどの範囲を測り、何を省略・推定したかが追跡できます。</li><li><strong>個体との対応：</strong>モデル調整に使わない刺激・介入・記憶課題で、平均・他個体モデルとの比較が成立します。評価の答えをモデルの追加調整で与えません。</li><li><strong>継続して働く：</strong>保持・忘却・新たな学習を含め、決めた期間と入出力条件で動作を維持します。</li><li><strong>独立に確かめる：</strong>別チームが追試でき、許容誤差、費用、遅延、未検証範囲を公開できます。</li></ul><p>δ・εなどの数値は、生体の反復測定と対象機能から事前に決めます。設計の詳細は<a href="/ja/validation.html#protocol">検証手順</a>へ進んでください。上記は本サイトの達成条件案で、既存の認証規格ではありません。</p>',
      '<p>The target is <strong>a whole-brain model based on measurements of a particular person that corresponds to their activity, previously learned information, learning capacity and body interaction over prespecified functions and timescales</strong>. This is a technical research target, not certification of perfect reproduction in every situation. Individual memories and skills are part of the 2008 roadmap’s criteria; purpose-dependent tests draw on fidelity research.[[9B7EMU3K]][[XKB4CG64]]</p><ul><li><strong>Traceable reconstruction:</strong> identify the individual, measured boundary, omissions and inferred information.</li><li><strong>Individual correspondence:</strong> compare with average and other-individual models on held-out stimuli, interventions and memory tasks, without teaching the evaluation answers.</li><li><strong>Continued operation:</strong> maintain function over specified periods and input/output conditions, including retention, forgetting and new learning.</li><li><strong>Independent verification:</strong> enable replication by another team and report tolerances, cost, latency and untested scope.</li></ul><p>Set numerical margins such as δ and ε in advance from biological repeats and the target function; see the <a href="/validation.html#protocol">validation procedure</a>. These are proposed success criteria, not an existing certification standard.</p>'),
    s('hardest-gaps', '2050年へ向けて、特に越える必要がある壁', 'The barriers that make 2050 demanding',
      '<div class="cards"><article class="card"><h3>1. 情報が十分に残るか</h3><p>構造がきれいに残っていても、機能に必要な状態を失っていれば復元できるとは限りません。保存研究と記憶課題をつなぐ実験が必要です。[[SDSWEA5J]][[LP5F3H2Q]]</p></article><article class="card"><h3>2. 地図から動作を決められるか</h3><p>同じ観測に合うモデルが複数あり得ます。未知の介入への応答まで比較し、必要な追加測定を選びます。[[274IXB72]][[XKB4CG64]]</p></article><article class="card"><h3>3. 全工程を実行できるか</h3><p>撮像速度だけでなく、試料処理、接続の追跡・校正、分子計測、モデル化、実行、独立検証をつなぐ必要があります。[[EVWH7H32]][[9B7EMU3K]]</p></article></div><p><strong>期限を厳しくする根拠：</strong>Collinsらの2025年の方式比較は、拡大顕微鏡とライトシート法による<strong>人の接続図</strong>についても、2025年の時点で、追加の技術進歩があれば約25〜50年後にプロジェクトが実行可能になるかもしれないと論じ、強い不確実性を明記しています。これは技術の成熟時期についての著者の見通しで、1回の撮像に要する時間でもWBEの完成予測でもありません。この方式についての見通しの早い側でも2050年前後です。同年に機能の独立検証まで目指す本案は、さらに厳しい挑戦目標です。取得・再構成の短縮と機能・記憶の実証を並行して進める必要があります。[[EVWH7H32]]</p><p><strong>取得経路の前提：</strong>本案は、固定後の構造取得を含む経路を中心にしています。生体を維持したまま全脳の必要情報を読む方式を選ぶ場合は、その計測能力も別の通過条件になります。保存で失われる情報を後から必ず補えるとは仮定しません。[[9B7EMU3K]][[SDSWEA5J]]</p>',
      '<div class="cards"><article class="card"><h3>1. Does sufficient information survive?</h3><p>Well-preserved structure need not retain every state required for function. Experiments must connect preservation to memory tests.[[SDSWEA5J]][[LP5F3H2Q]]</p></article><article class="card"><h3>2. Can a map determine function?</h3><p>Several models can fit the same observations. Compare unseen interventions to select the additional measurements that matter.[[274IXB72]][[XKB4CG64]]</p></article><article class="card"><h3>3. Can the whole workflow run?</h3><p>Imaging speed must be joined to tissue processing, tracing and correction, molecular measurements, modelling, execution and independent validation.[[EVWH7H32]][[9B7EMU3K]]</p></article></div><p><strong>Why the deadline is demanding:</strong> Collins et al.’s 2025 comparison suggests that even a <strong>human connectome</strong> project using expansion and light-sheet microscopy might become feasible roughly 25–50 years after 2025, conditional on further technical advances and with substantial uncertainty. This is the authors’ projection of technological readiness, not the duration of a single imaging run or a WBE completion forecast. Even the earlier end of this projection for this approach is around 2050. Requiring independent functional validation in that same year makes this proposal a more demanding stretch target. It would require faster acquisition/reconstruction and parallel evidence for function and memory.[[EVWH7H32]]</p><p><strong>Acquisition-route assumption:</strong> this plan centres on routes that can include post-fixation structural measurements. A route that keeps the biological brain functioning while acquiring all necessary information requires an additional measurement capability. We do not assume that information lost during preservation can always be recovered later.[[9B7EMU3K]][[SDSWEA5J]]</p>'),
    s('early',
      '古い構想を、現在の証拠と混ぜない',
      'Keep historical proposals in their context',
      '<p>Joseph StroutのMind Uploading Home Pageは、走査、計算機、置換などの技術的構想を整理した初期ウェブ資料です。ページは2006年の更新日を示しています。研究課題の歴史を知る資料として有用ですが、現在の解像度、費用、計算性能、達成状況の根拠にはそのまま使えません。[[STROUT]]</p><p>SandbergとBostromの2008年の技術ロードマップは、保存から走査、解釈、シミュレーションまでを依存関係として整理しました。その枠組みは参照点になりますが、当時の数値見積もりは現在の実測や方式に照らして更新する必要があります。[[9B7EMU3K]]</p>',
      "<p>Joseph Strout's Mind Uploading Home Page is an early web resource organizing scanning, computation, and replacement proposals. It displays a 2006 update date. It is useful historical context, but its resolution, cost, computing, and feasibility assumptions are not current evidence.[[STROUT]]</p><p>Sandberg and Bostrom's 2008 technical roadmap organized preservation, scanning, interpretation, and simulation as dependencies. Its framework remains a reference point; quantitative estimates need reassessment against current measurements and methods.[[9B7EMU3K]]</p>"),
    s('timeline',
      '技術の積み重ね',
      'A sequence of technical advances',
      '<ol class="beats"><li class="beat"><span class="beat-date">1952</span><h3>電気的な動作を数式で記述</h3><p>Hodgkin–Huxleyモデルは膜電流を定量的に扱う基盤です。細胞の動作モデルと、個体全体の再現の距離を考える出発点になります。[[ADD207]]</p></li><li class="beat"><span class="beat-date">1986</span><h3>線虫の接続図という歴史的基盤</h3><p>Whiteらによる<i>C. elegans</i>の神経系の配線記述は、その後の全身接続図と回路研究の基盤となりました。この歴史的な位置付けは、先行研究を更新したCookら（2019）の記述に基づきます。接続図の作成と、動作する個体モデルの検証は別の課題です。[[ADD192]]</p></li><li class="beat"><span class="beat-date">2008</span><h3>WBEの工程と依存関係を整理</h3><p>SandbergとBostromのロードマップは、保存、走査、解釈、シミュレーションをつなぐ技術要件を整理しました。工程を分けて考える枠組みであり、現在の装置性能や完成年を保証するものではありません。[[9B7EMU3K]]</p></li><li class="beat"><span class="beat-date">2014</span><h3>神経系と身体をつなぐ公開モデルの構想</h3><p>OpenWormのPerspectiveは、<i>C. elegans</i>を対象とした統合モデルの構想と公開研究基盤を紹介しました。当時の設計と計画を示す資料であり、個体の全機能を再現した完成報告としては扱いません。[[8ZGBRSYV]]</p></li><li class="beat"><span class="beat-date">2018</span><h3>成体ハエの全脳EM画像を公開</h3><p>Zhengらは成体雌ハエ1個体の全脳EM画像ボリューム（FAFB）を公開し、選択した回路で追跡可能性を検証しました。これは画像の全脳取得の節目であり、この時点で全ニューロンの接続図を完成させた報告ではありません。後のFlyWireは、この画像を利用して再構成を進めました。[[ZHENG2018]][[ADD196]]</p></li><li class="beat"><span class="beat-date">2019</span><h3>線虫の雌雄を全身の接続図へ</h3><p>Cookらは<i>C. elegans</i>の雌雄同体と雄について、感覚入力から筋肉などの出力先までを含む接続図を示しました。複数個体の画像と一部の外挿を組み合わせた図であり、単一個体の全状態を測定した記録ではありません。[[ADD192]]</p></li><li class="beat"><span class="beat-date">2020</span><h3>中央脳の密な再構成と、マウス全脳への提案</h3><p>Schefferらのhemibrainは、成体雌ハエ1個体の中央脳の大部分を密に再構成し、約25,000ニューロンを約2,000万の化学シナプスで結びました。細胞型・回路解析とデータ再利用の基盤ですが、全脳接続図の完成や機能・記憶の再現とは区別します。[[SCHEFFER2020]]</p><p>同年、Abbottらはマウス全脳のシナプス接続図を、細胞型・長距離結合・個体差を調べる研究基盤として提案しました。自動化、切片の損失、計算量、費用を論じた論説であり、マウス全脳の再構成や機能再現を達成した報告ではありません。[[ISSUE282_ABBOTT2020]]</p></li><li class="beat"><span class="beat-date">2023–2024</span><h3>ハエの脳規模の接続図と機能予測</h3><p>幼生脳の接続図と、FAFBから再構成した成体脳のFlyWire接続図が公開されました。接続に制約されたモデルによる視覚系の機能予測も前進しています。構造の完成度と、予測した機能の範囲は分けて評価します。[[ADD209]][[ADD196]][[XMYSQXY8]]</p></li><li class="beat"><span class="beat-date">2025</span><h3>対応を測り、比較する</h3><p>MICrONS、LICONN、ZAPBench、忠実度の研究が、構造と活動の対応、分子情報を伴う再構成、予測性能の比較、用途ごとの評価という課題を具体化しました。[[6TNZ57MZ]][[ADD198]][[FHPYMIG8]][[XKB4CG64]]</p></li><li class="beat"><span class="beat-date">2026</span><h3>脳と身体を結び付ける</h3><p>脳と腹側神経索を結ぶ統合データが発展しました。[[ADD199]][[ADD188]] 身体を含むモデルのプロジェクト発表と、それをアップロードと呼べるかについての議論もあります。公式な技術説明、論文で検証した結果、個体の機能・記憶の再現を区別する必要があります。[[EON]][[CCFLY]]</p></li></ol>',
      '<ol class="beats"><li class="beat"><span class="beat-date">1952</span><h3>Quantifying electrical dynamics</h3><p>The Hodgkin–Huxley model provides a foundation for membrane-current modelling. It also illustrates the distance between modelling a cellular process and reproducing an individual organism.[[ADD207]]</p></li><li class="beat"><span class="beat-date">1986</span><h3>The foundational worm wiring diagram</h3><p>White et al.’s description of wiring in the <i>C. elegans</i> nervous system provided a foundation for later whole-animal connectomes and circuit studies. This historical attribution follows Cook et al. (2019), which updated the earlier work. Constructing a wiring diagram and validating a functioning model of an individual remain separate tasks.[[ADD192]]</p></li><li class="beat"><span class="beat-date">2008</span><h3>Organising WBE requirements and dependencies</h3><p>Sandberg and Bostrom’s roadmap organised the technical requirements linking preservation, scanning, interpretation and simulation. It provides a framework for separating stages, rather than establishing current instrument performance or a completion date.[[9B7EMU3K]]</p></li><li class="beat"><span class="beat-date">2014</span><h3>An open modelling programme linking nervous system and body</h3><p>The OpenWorm perspective described an integrated modelling programme and open research infrastructure for <i>C. elegans</i>. It documents the design and plans at that time, rather than reporting completed reproduction of all functions of an individual.[[8ZGBRSYV]]</p></li><li class="beat"><span class="beat-date">2018</span><h3>A whole-brain EM image volume of an adult fly</h3><p>Zheng et al. released the FAFB EM image volume of one adult female fly brain and validated tracing in selected circuits. This was a milestone in whole-brain imaging, rather than a completed reconstruction of every neuron’s connections. FlyWire later built its reconstruction from these images.[[ZHENG2018]][[ADD196]]</p></li><li class="beat"><span class="beat-date">2019</span><h3>Whole-animal connectomes of both worm sexes</h3><p>Cook et al. presented connectomes of hermaphrodite and male <i>C. elegans</i>, spanning sensory inputs and outputs to muscles and other organs. They combine images from several animals with some extrapolation; they are not measurements of every state in one individual.[[ADD192]]</p></li><li class="beat"><span class="beat-date">2020</span><h3>Dense central-brain reconstruction and a mouse whole-brain proposal</h3><p>Scheffer et al.’s hemibrain densely reconstructed a large portion of one adult female fly’s central brain, linking about 25,000 neurons through about 20 million chemical synapses. It supports cell-type analysis, circuit studies and reuse, while remaining distinct from a completed whole-brain connectome or reproduction of function and memory.[[SCHEFFER2020]]</p><p>In the same year, Abbott et al. proposed a synapse-level mouse whole-brain connectome as a resource for cell types, long-range wiring and individual variation. This commentary discusses automation, section loss, computation and cost; it does not report completed mouse whole-brain reconstruction or functional emulation.[[ISSUE282_ABBOTT2020]]</p></li><li class="beat"><span class="beat-date">2023–2024</span><h3>Fly-brain connectomes and functional prediction</h3><p>The larval brain connectome and the adult FlyWire connectome reconstructed from FAFB became available. Connectome-constrained models also advanced functional prediction in the visual system. Structural coverage and the range of predicted functions require separate evaluation.[[ADD209]][[ADD196]][[XMYSQXY8]]</p></li><li class="beat"><span class="beat-date">2025</span><h3>Measuring and benchmarking correspondence</h3><p>MICrONS, LICONN, ZAPBench and fidelity research sharpened questions about structure–activity correspondence, reconstruction with molecular information, predictive benchmarking and evaluation for particular purposes.[[6TNZ57MZ]][[ADD198]][[FHPYMIG8]][[XKB4CG64]]</p></li><li class="beat"><span class="beat-date">2026</span><h3>Linking brains with bodies</h3><p>Integrated datasets linking brain and ventral nerve cord advanced.[[ADD199]][[ADD188]] Project announcements of embodied models also prompted debate about calling them uploads. Official technical accounts, results tested in papers, and reproduction of an individual’s functions and memories need to be distinguished.[[EON]][[CCFLY]]</p></li></ol>'),
    s('review',
      'レビューは、入口として使う',
      'Use reviews as entry points',
      '<p><em>State of Brain Emulation Report 2025</em>は関連技術を整理した総説です。本サイトは、2026年公開の最終版（182ページ）を参照しています。題名の「2025」と最終版の公開年を区別してください。技術の見通しや費用の推定を、個別実験で達成した結果とは分けて読みます。[[REPORTFINAL]]</p>',
      "<p><em>State of Brain Emulation Report 2025</em> is a broad technical review. This guide uses the 182-page final report released in 2026; the title's “2025” is distinct from that release year. Projections and cost estimates should be separated from experimentally achieved results.[[REPORTFINAL]]</p>"),
    s('contribute', '現在の研究を、次の判定へつなぐ', 'Connect today’s work to the next gate',
      '<p>Carboncopiesは、更新ロードマップで課題を整理し、BrainGenixとBrain Emulation Challengeで測定からモデルへの変換・評価の基盤を整えています。公式ページに示された活動と、このページの2050年案は区別してください。[[CCROADMAP]][[CCRESEARCH]][[CCCHALLENGE]]</p><p>今すぐ始めるなら、<a href="/ja/action.html">既存の接続図モデルを再現し、誤差が機能予測をどう変えるか調べる研究</a>が、2030年段階の具体的な入口です。進捗は「新しい論文の数」だけでなく、どの通過条件が新たに満たされたかで更新します。</p>',
      '<p>Carboncopies organises open questions through its roadmap update and develops measurement-to-model and evaluation infrastructure through BrainGenix and the Brain Emulation Challenge. Distinguish those officially described activities from this page’s 2050 plan.[[CCROADMAP]][[CCRESEARCH]][[CCCHALLENGE]]</p><p>A concrete entry point for the 2030 stage is <a href="/action.html">reproducing an existing connectome model and testing how reconstruction errors alter functional predictions</a>. Track which gates gain evidence, alongside new publications.</p>'),
])

page('resources',
     '文献・データ・用語',
     'Literature, data, and terminology',
     '直接WBEを扱う研究から、計測、記憶、逆問題、神経プロテーゼ、計算基盤までをたどれます。',
     'Explore direct WBE research and enabling work on measurement, memory, inverse problems, neural prosthetics, and computing.', [
    s('glossary',
      '用語を確認する',
      'Look up a term',
      '<p>用語の定義は<a href="/ja/science.html#glossary">科学的基礎の冒頭</a>にまとめています。</p>',
      '<p>Definitions are at the <a href="/science.html#glossary">start of the foundations page</a>.</p>'),
    s('start',
      '最初に読む資料',
      'Start here',
      '<p><strong>全体像：</strong>2008年ロードマップとState of Brain Emulation Report。<strong>計測：</strong>Collinsらの方式比較とLICONN。<strong>同定：</strong>LappalainenらとHanらの検証研究。<strong>評価：</strong>LinssenとKoene、ZAPBench、Brain Emulation Challengeが入口になります。[[9B7EMU3K]][[REPORTFINAL]][[EVWH7H32]][[ADD198]][[XMYSQXY8]][[274IXB72]][[XKB4CG64]][[FHPYMIG8]][[CCCHALLENGE]]</p>',
      "<p><strong>Overview:</strong> the 2008 roadmap and State of Brain Emulation Report. <strong>Measurement:</strong> Collins et al.'s modality comparison and LICONN. <strong>Identification:</strong> Lappalainen et al. and Han et al. <strong>Evaluation:</strong> Linssen and Koene, ZAPBench, and the Brain Emulation Challenge.[[9B7EMU3K]][[REPORTFINAL]][[EVWH7H32]][[ADD198]][[XMYSQXY8]][[274IXB72]][[XKB4CG64]][[FHPYMIG8]][[CCCHALLENGE]]</p>"),
    s('library',
      '本文確認済みの参考文献',
      'Full-text-reviewed references',
      '<p>以下は<strong>取得した本文を確認し、本解説に使用した文献</strong>です。取得版に含まれる本文・方法・結果・考察・付録を対象とし、各項目に確認範囲を記録しています。図説明の読了と図像の目視確認は区別します。別添補足・元データ・未取得の図像まで一律に確認したという意味ではなく、論文の追試でもありません。</p><p>未取得資料と、保管だけを行った未読資料は公開引用から除外しています。</p>{{library}}',
      '<p>This catalogue contains sources whose acquired full text was reviewed and used in the guide. Coverage includes the text, methods, results, discussion and appendices present in the acquired version, as recorded per entry. Reading captions is distinct from visually inspecting figures. This does not claim uniform review of separate supplements, source data or unavailable images, nor experimental replication.</p><p>Unavailable sources and stored-but-unread material are excluded from public citations.</p>{{library}}'),
    s('repository',
      '本サイトの原稿・更新履歴',
      'Site source and revision history',
      '<p>本サイトは<strong><a href="https://github.com/yasufumi-nakata">yasufumi-nakata</a>が執筆・編集する個人の研究ガイド</strong>です。Carboncopies Foundationの公開資料は引用元として使用しています。同団体の公式サイト、公式声明、監修・承認を受けた文書として発行するものではありません。</p><p>内容への連絡や訂正依頼は<a href="https://github.com/yasufumi-nakata/mind-upload/issues">GitHub Issues</a>へお寄せください。該当ページ、節、問題の記述と根拠を記載してください。確認後に本文と更新記録へ反映し、根拠が確定しない場合は不確実性を明記します。<a href="https://github.com/yasufumi-nakata/mind-upload/commits/main/">全変更履歴</a>から旧版との差分を確認できます。</p>',
      '<p>This is a <strong>personal research guide written and edited by <a href="https://github.com/yasufumi-nakata">yasufumi-nakata</a></strong>. Public Carboncopies Foundation material is used as cited source material. The site is not issued as an official Foundation website, statement, supervised publication or endorsed document.</p><p>Send questions or correction requests through <a href="https://github.com/yasufumi-nakata/mind-upload/issues">GitHub Issues</a>, identifying the page, section, statement and supporting evidence. Verified corrections are reflected in the text and revision record; unresolved evidence is marked as uncertain. The <a href="https://github.com/yasufumi-nakata/mind-upload/commits/main/">complete change history</a> provides differences from earlier versions.</p>'),
    s('citation-rights',
      '本サイトの引用・再利用条件',
      'Citing and reusing this site',
      '<p>引用例：<strong>yasufumi-nakata. <em>Mind Uploading Research Guide</em>. {{edition_date}}版. https://mind-upload.com/.</strong>利用したページの題名・URL・閲覧日を併記してください。厳密に同じ版を指す場合は、GitHubの変更履歴から該当コミットの固定URLも記録してください。機械可読の書誌は<a href="/CITATION.cff" download>CITATION.cff</a>にあります。DOIは付与していません。</p><p><strong>本サイト全体への包括的な再利用許諾は付与していません。</strong>第三者の論文・図版等には各資料の条件が適用されます。CC BYなどの図版条件を本サイト全体へ拡張しないでください。以前の版は、その版に付された条件を参照してください。再利用の相談は上記の連絡先へお寄せください。</p>',
      '<p>Suggested citation: <strong>yasufumi-nakata. <em>Mind Uploading Research Guide</em>. Edition {{edition_date}}. https://mind-upload.com/.</strong> Include the title and URL of the page used and your access date. For a fixed revision, also record its commit permalink from the GitHub history. Machine-readable metadata are in <a href="/CITATION.cff" download>CITATION.cff</a>. No DOI has been assigned.</p><p><strong>No blanket reuse license is granted for this site.</strong> Third-party papers and figures retain their own terms. Figure licenses such as CC BY do not apply to the entire site. Consult the terms attached to any earlier version when using that version. Direct reuse enquiries to the contact above.</p>'),
    s('method',
      '探索範囲と引用の方法',
      'Search scope and citation method',
      '<p>Carboncopiesの公開文献集とFAQ・研究ページ、Stroutの歴史資料、既存サイトの引用を入口に、関連する計測、システム同定、機能予測、神経補綴の資料を集めました。2026年11月6日の追補では、Issue #282–292で挙がった20件のDOIをScopusで照会し、検索結果19件の書誌を保存しました。その後、出版社・PMC・大学公開版の本文を取得し、今回の論点に必要な文献を確認して採用しました。Scopusの検索一致やダウンロード完了表示だけを本文確認の根拠にはしていません。候補の全件採用やデータベースの網羅検索ではありません。哲学・倫理は本解説の対象にしません。[[CCLIBRARY]][[CCFAQ]][[STROUT]]</p><p>引用はページごとの番号式です。著者、題名、年、媒体、巻号・ページまたは論文番号、DOIまたは原文URLを記載します。著者が多い場合は先頭6名と「et al.」を表示します。ウェブ資料には確認日を付け、査読論文、プレプリント、技術報告、団体の公式説明を区別します。</p><p>全文の確認は、保存したPDFまたは当該ウェブページの本文が対象です。別ファイルとして提供される未取得の補足資料まで読了したという意味ではありません。書籍から章を用いた場合は、その章の範囲を明記します。研究提案は本サイトの提案と示し、原著の実施結果と混同しません。</p><p>対象範囲を定めた文献ガイドであり、完全網羅を保証するシステマティックレビューではありません。本文は公開サイトに再配布せず、正規の配布先へ案内します。</p>',
      "<p>The collection began with Carboncopies' public library, FAQ and research pages, Strout's historical resource and the previous site's references, extending into measurement, system identification, functional prediction and neuroprosthetics. For the 6 November 2026 update, 20 DOIs raised by Issues #282–292 were queried in Scopus and bibliographic records for 19 results were saved. Full texts were then acquired from publishers, PMC and university repositories, with relevant sources reviewed before adoption. A Scopus match or download notification alone was not treated as full-text review. This was neither adoption of every candidate nor an exhaustive database search. Philosophy and ethics are outside this guide's scope.[[CCLIBRARY]][[CCFAQ]][[STROUT]]</p><p>Citations are numbered within each page. Records include authors, title, year, venue, volume/issue/pages or article number, and DOI or source URL. Long author lists display six names followed by “et al.” Web resources have access dates; peer-reviewed papers, preprints, technical reports and organisational statements are distinguished.</p><p>Full-text review covers the saved PDF or the cited webpage, not separate supplementary files that were not acquired. For a book chapter, the chapter scope is stated. Proposed experiments are explicitly identified as proposals, separate from original findings.</p><p>This is a scoped literature guide, not an exhaustive systematic review. The public site links to legitimate distribution sources rather than redistributing full texts.</p>"),
    s('changes',
      '今回の主な更新',
      'Changes in this edition',
      '<p>{{edition_date}}：Issue #282–292に対応して、撮像速度に基づく条件、グリア・シナプス外伝達、個体比較、近似事後分布、統計的な判定手順、人で必要な参照記録を追補しました。年表、シナプス数と接続数、著者・BibTeXも修正し、個人サイトとしての編集方針・引用方法・再利用条件を明記しました。</p><p>1986年の起点は既読のCookらによる歴史的帰属として記載し、Whiteらの原著全体を今回読了した扱いにはしていません。Markramら（2015）の候補は今回の本文確認が完了していないため、確認済み文献と年表への直接採用を保留しました。[[ADD192]]</p>',
      '<p>{{edition_date}}: In response to Issues #282–292, this update adds throughput conditions, glial and extrasynaptic mechanisms, individual comparisons, approximate posteriors, statistical decision procedures and human reference-data requirements. It also revises historical milestones, synapse-versus-edge counts, author records and BibTeX, and specifies the personal site’s editorial, citation and reuse policies.</p><p>The 1986 starting point is attributed through the reviewed Cook et al. paper, not presented as a new full-text review of the White et al. original. The Markram et al. (2015) candidate remains outside the reviewed catalogue and direct timeline citations because its full-text review was not completed in this update.[[ADD192]]</p>'),
])
